private fun collapseNow() {
    val lp = params ?: return
    if (!menuExpanded.value) return
    menuExpanded.value = false
    setWindowFocusable(false)
    lp.width = dp(BTN_DP)
    lp.height = dp(BTN_DP)
    clampToScreen(lp)
    snapToCorner(lp)
    savePanelPosition(lp)
