/**
 * Детальный экран одного скриншота.
 *
 * Два режима просмотра:
 *  1) Оверлей — Canvas рисует распознанные регионы в их координатах
 *     (нормализованные 0..1) на «странице»-заглушке. Текст виден
 *     в тех же позициях, что и на оригинальном изображении.
 *  2) Список — как было: текст + координаты + номера регионов.
 *
 * Кнопка «Diff» переключает на экран сравнения двух скриншотов.
 */
class ScreenshotDetailScreen(
    private val entryId: Long,
    private val compareWithId: Long? = null,
) : YomikaiScreen() {

    @OptIn(ExperimentalMaterial3Api::class)
    @Composable
    override fun Content() {
        val navigator = LocalNavigator.currentOrThrow
        val entries by OcrScreenshotBuffer.entries.collectAsState()
        val entry = entries.firstOrNull { it.id == entryId }
        val compareEntry = compareWithId?.let { id -> entries.firstOrNull { it.id == id } }
        val dateFormat = remember { SimpleDateFormat("HH:mm:ss, dd.MM", Locale.getDefault()) }
        var showDiff by remember { mutableStateOf(compareEntry != null) }

        Column(modifier = Modifier.fillMaxSize()) {
            TopAppBar(
                title = {
                    Text(
                        if (entry != null) "Стр. ${entry.pageIndex + 1} — ${dateFormat.format(Date(entry.timestamp))}"
                        else "Скриншот",
                    )
                },
                navigationIcon = {
                    IconButton(onClick = {
                        navigator.pop()
                    }) {
                        Icon(Icons.AutoMirrored.Outlined.ArrowBack, contentDescription = "Назад")
                    }
                },
                actions = {
                    if (compareEntry != null) {
                        IconButton(onClick = { showDiff = !showDiff }) {
                            Icon(Icons.Outlined.SwapHoriz, contentDescription = "Diff")
                        }
                    }
                },
            )

            if (entry == null) {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Text("Скриншот не найден", color = MaterialTheme.colorScheme.onSurfaceVariant)
                }
                return@Content
            }

            if (showDiff && compareEntry != null) {
                DiffView(
                    entryA = compareEntry,
                    entryB = entry,
                )
            } else {
                OverlayView(entry)
            }
        }
    }

    @Composable
    private fun OverlayView(entry: OcrScreenshotEntry) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .verticalScroll(rememberScrollState())
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            Row(
                horizontalArrangement = Arrangement.spacedBy(12.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Text("Движок: ${entry.engineUsed}", style = MaterialTheme.typography.labelMedium)
                Text("Регионов: ${entry.regions.size}", style = MaterialTheme.typography.labelMedium)
                Text(
                    "Размер: ${entry.imageWidth}×${entry.imageHeight}",
                    style = MaterialTheme.typography.labelMedium,
                )
            }

            // ===== Canvas-оверлей: рисуем регионы в координатах OCR =====
            Text(
                "Визуальный оверлей:",
                style = MaterialTheme.typography.titleSmall,
                color = MaterialTheme.colorScheme.primary,
            )

            val hasImage = entry.imagePath != null && File(entry.imagePath).exists()
            if (hasImage) {
                // Настоящий кадр (JPEG, снятый при авточтении) с оверлеем регионов.
                // Box имеет пропорции кадра, поэтому Fit-изображение и регионы
                // (нормализованные 0..1 к размеру кадра) совпадают по позициям.
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .aspectRatio(
                            if (entry.imageHeight > 0) {
                                entry.imageWidth.toFloat() / entry.imageHeight
                            } else {
                                3f / 4f
                            },
                        )
                        .clip(RoundedCornerShape(8.dp)),
                ) {
                    AsyncImage(
                        model = File(entry.imagePath),
                        contentDescription = null,
                        modifier = Modifier.fillMaxSize(),
                        contentScale = ContentScale.Fit,
                    )
                    RegionOverlay(
                        entry = entry,
                        modifier = Modifier.matchParentSize(),
                        drawGrid = false,
                    )
                }
            } else {
                RegionOverlay(
                    entry = entry,
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(420.dp),
                    drawGrid = true,
                )
            }

            // ===== Текстовый список =====
            Text(
                "Полный текст:",
                style = MaterialTheme.typography.titleSmall,
                color = MaterialTheme.colorScheme.primary,
            )
            Text(
                entry.summaryText,
                style = MaterialTheme.typography.bodyMedium,
            )

            Text(
                "Регионы:",
                style = MaterialTheme.typography.titleSmall,
                color = MaterialTheme.colorScheme.primary,
            )
            entry.regions.forEach { region ->
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(6.dp))
                        .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f))
                        .padding(8.dp),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    Text(
                        "#${region.order}",
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.primary,
                    )
                    Text(
                        "[${String.format("%.2f", region.left)},${String.format("%.2f", region.top)}," +
                            "${String.format("%.2f", region.right)},${String.format("%.2f", region.bottom)}]",
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                    Text(
                        region.text,
                        style = MaterialTheme.typography.bodySmall,
                    )
                }
            }
        }
    }

    /**
     * Canvas с рамками распознанных регионов. Поверх настоящего кадра
     * (drawGrid = false) или на «странице»-заглушке с сеткой (drawGrid = true).
     * Координаты регионов нормализованы 0..1 к размеру кадра, поэтому при
     * пропорциональном боксе оверлей ложится точно на текст.
     */
    @Composable
    private fun RegionOverlay(
        entry: OcrScreenshotEntry,
        modifier: Modifier,
        drawGrid: Boolean,
    ) {
        val regionColors = listOf(
            Color(0x8800E5FF), Color(0x88FF6D00), Color(0x88AA00FF),
            Color(0x8800E676), Color(0x88FFD600), Color(0x88FF1744),
        )
        Canvas(
            modifier = if (drawGrid) {
                modifier
                    .clip(RoundedCornerShape(8.dp))
                    .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f))
            } else {
                modifier.clip(RoundedCornerShape(8.dp))
            },
        ) {
            val canvasW = size.width
            val canvasH = size.height

            // Сетка-подложка (только для режима без изображения)
            if (drawGrid) {
                for (i in 1..4) {
                    drawLine(
                        color = Color.LightGray.copy(alpha = 0.3f),
                        start = Offset(0f, canvasH * i / 5),
                        end = Offset(canvasW, canvasH * i / 5),
                        strokeWidth = 1f,
                    )
                    drawLine(
                        color = Color.LightGray.copy(alpha = 0.3f),
                        start = Offset(canvasW * i / 5, 0f),
                        end = Offset(canvasW * i / 5, canvasH),
                        strokeWidth = 1f,
                    )
                }
            }

            val paint = android.graphics.Paint().apply {
                textSize = 11.sp.toPx()
                isAntiAlias = true
            }

            entry.regions.forEachIndexed { idx, region ->
                val color = regionColors[idx % regionColors.size]
                val x1 = region.left * canvasW
                val y1 = region.top * canvasH
                val w = (region.right - region.left) * canvasW
                val h = (region.bottom - region.top) * canvasH
                if (w <= 0f || h <= 0f) return@forEachIndexed

                // Фон региона
                drawRect(
                    color = color.copy(alpha = if (drawGrid) 0.25f else 0.18f),
                    topLeft = Offset(x1, y1),
                    size = Size(w, h),
                )
                // Рамка
                drawRect(
                    color = color.copy(alpha = 0.7f),
                    topLeft = Offset(x1, y1),
                    size = Size(w, h),
                    style = androidx.compose.ui.graphics.drawscope.Stroke(width = 1.5f),
                )
                // Номер + текст
                paint.color = android.graphics.Color.WHITE
                drawContext.canvas.nativeCanvas.drawText(
                    "#${idx + 1}",
                    x1 + 3f,
                    y1 + 12f,
                    paint,
                )
                val textLines = region.text.chunked((w / 5f).toInt().coerceAtLeast(8))
                paint.color = if (drawGrid) android.graphics.Color.DKGRAY else android.graphics.Color.WHITE
                textLines.take(3).forEachIndexed { li, line ->
                    drawContext.canvas.nativeCanvas.drawText(
                        line,
                        x1 + 3f,
                        y1 + 24f + li * 13f,
                        paint,
                    )
                }
            }
        }
    }

    /**
     * Diff-вью: два скриншота бок о бок. Слева — A (старый), справа — B (новый).
     * Регионы, которых нет в A — подсвечены зелёным, в A, но нет в B — красным.
     * Совпадающие — серым.
     */
    @Composable
    private fun DiffView(entryA: OcrScreenshotEntry, entryB: OcrScreenshotEntry) {
        val regionColorsA = Color(0x88FF1744)  // красный — удалено
        val regionColorsB = Color(0x8800E676)  // зелёный — добавлено
        val regionColorsSame = Color(0x889E9E9E) // серый — совпадает

        val textsA = entryA.regions.map { it.text }.toSet()
        val textsB = entryB.regions.map { it.text }.toSet()

        Column(
            modifier = Modifier
                .fillMaxSize()
                .verticalScroll(rememberScrollState())
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            Row(
                horizontalArrangement = Arrangement.spacedBy(12.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Text("A: стр. ${entryA.pageIndex + 1}", style = MaterialTheme.typography.labelMedium, color = Color(0xFFFF1744))
                Text("B: стр. ${entryB.pageIndex + 1}", style = MaterialTheme.typography.labelMedium, color = Color(0xFF00E676))
                Text("Разница: ${textsB.size - textsA.size} регионов", style = MaterialTheme.typography.labelMedium)
            }

            Text(
                "Разница (A → B):",
                style = MaterialTheme.typography.titleSmall,
                color = MaterialTheme.colorScheme.primary,
            )

            // Тексты, удалённые из A
            val removed = textsA - textsB
            if (removed.isNotEmpty()) {
                Text("Удалено (${removed.size}):", style = MaterialTheme.typography.labelMedium, color = Color(0xFFFF1744))
                removed.forEach { t ->
                    Text("− $t", style = MaterialTheme.typography.bodySmall, color = Color(0xFFFF1744))
                }
            }

            // Тексты, добавленные в B
            val added = textsB - textsA
            if (added.isNotEmpty()) {
                Text("Добавлено (${added.size}):", style = MaterialTheme.typography.labelMedium, color = Color(0xFF00E676))
                added.forEach { t ->
                    Text("+ $t", style = MaterialTheme.typography.bodySmall, color = Color(0xFF00E676))
                }
            }

            // Canvas-оверлей B с подсветкой diff
            Canvas(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(420.dp)
                    .clip(RoundedCornerShape(8.dp))
                    .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f)),
            ) {
                val canvasW = size.width
                val canvasH = size.height

                entryB.regions.forEach { region ->
                    val color = if (region.text in textsA) regionColorsSame else regionColorsB
                    val x1 = region.left * canvasW
                    val y1 = region.top * canvasH
                    val w = (region.right - region.left) * canvasW
                    val h = (region.bottom - region.top) * canvasH

                    drawRect(
                        color = color.copy(alpha = 0.25f),
                        topLeft = Offset(x1, y1),
                        size = Size(w, h),
                    )
                    drawRect(
                        color = color.copy(alpha = 0.7f),
                        topLeft = Offset(x1, y1),
                        size = Size(w, h),
                        style = androidx.compose.ui.graphics.drawscope.Stroke(width = 1.5f),
                    )

                    val paint = android.graphics.Paint().apply {
                        textSize = 10.sp.toPx()
                        isAntiAlias = true
                    }
                    paint.color = android.graphics.Color.DKGRAY
                    val textLines = region.text.chunked((w / 5f).toInt().coerceAtLeast(8))
                    textLines.take(3).forEachIndexed { li, line ->
                        drawContext.canvas.nativeCanvas.drawText(
                            line,
                            x1 + 3f,
                            y1 + 14f + li * 12f,
                            paint,
                        )
                    }
                }
            }
        }
    }
}

package mihon.data.ocr

import android.content.Context
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import logcat.LogPriority
import mihon.domain.ocr.model.OcrRegion
import tachiyomi.core.common.util.system.logcat
import java.io.File

/**
 * Кольцевой буфер скриншотов авточтения — текст регионов (~1-5 KB) плюс
 * необязательный JPEG-кадр каждого скриншота.
 *
 * Хранит до [MAX_ENTRIES] последних записей в JSON-файле. Если запись создана
 * с JPEG-кадром ([OcrScreenshotEntry.add]), картинка пишется в каталог
 * `filesDir/screenshots_images/<id>.jpg`, а в записи сохраняется её путь —
 * галерея показывает реальное изображение с оверлеем регионов.
 *
 * При превышении лимита самая старая запись и её файл удаляются.
 */
object OcrScreenshotBuffer {

    private const val DEFAULT_MAX_ENTRIES = 50
    private const val FILE_NAME = "screenshots.json"
    private const val IMAGE_DIR_NAME = "screenshots_images"

    /** Лимит записей (кольцевой буфер). Меняется через dev-панель. */
    @kotlin.jvm.Volatile
    var maxEntries: Int = DEFAULT_MAX_ENTRIES

    private val json = Json { ignoreUnknownKeys = true; encodeDefaults = true; prettyPrint = false }

    private val _entries = MutableStateFlow<List<OcrScreenshotEntry>>(emptyList())
    val entries: StateFlow<List<OcrScreenshotEntry>> = _entries.asStateFlow()

    /** Последний добавленный скриншот — для индикатора в углу читалки. */
    private val _lastEntry = MutableStateFlow<OcrScreenshotEntry?>(null)
    val lastEntry: StateFlow<OcrScreenshotEntry?> = _lastEntry.asStateFlow()

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
    private var persistFile: File? = null
    private var imagesDir: File? = null
    private var initialized = false

    fun init(context: Context) {
        if (initialized) return
        initialized = true
        persistFile = File(context.filesDir, FILE_NAME)
        imagesDir = File(context.filesDir, IMAGE_DIR_NAME).apply { mkdirs() }
        load()
    }

    // ---- Публичные методы ----

    /**
     * Добавить запись скриншота (текст + регионы ~1-5 KB, плюс необязательный
     * JPEG-кадр [imageJpeg], который пишется файлом и показывается в галерее).
     * Если буфер полон — самая старая запись (и её файл) удаляется.
     *
     * @return Созданная запись.
     */
    fun add(
        chapterId: Long,
        pageIndex: Int,
        scrollFraction: Float,
        regions: List<OcrRegion>,
        engineUsed: String,
        imageWidth: Int = 0,
        imageHeight: Int = 0,
        imageJpeg: ByteArray? = null,
        scanRegion: String = "viewport",
    ): OcrScreenshotEntry {
        val id = System.currentTimeMillis()
        val serializableRegions = regions.map { SerializableOcrRegion.fromOcrRegion(it) }
        val summaryText = regions.joinToString(" ") { it.text.trim() }.trim()
        val imagePath = imageJpeg?.let { jpeg ->
            imagesDir?.let { dir ->
                File(dir, "$id.jpg").apply { writeBytes(jpeg) }.absolutePath
            }
        }
        val entry = OcrScreenshotEntry(
            id = id,
            chapterId = chapterId,
            pageIndex = pageIndex,
            scrollFraction = scrollFraction,
            timestamp = id,
            regions = serializableRegions,
            engineUsed = engineUsed,
            summaryText = summaryText,
            imageWidth = imageWidth,
            imageHeight = imageHeight,
            imagePath = imagePath,
            scanRegion = scanRegion,
        )

        val current = _entries.value.toMutableList()
        val limit = maxEntries.coerceAtLeast(1)
        if (current.size >= limit) {
            val evicted = current.removeFirst()
            deleteImageFile(evicted)
        }
        current.add(entry)
        _entries.value = current
        _lastEntry.value = entry
        persist()
        return entry
    }

    /** Все скриншоты для конкретной главы (в порядке добавления). */
    fun forChapter(chapterId: Long): List<OcrScreenshotEntry> =
        _entries.value.filter { it.chapterId == chapterId }

    /** Все скриншоты для конкретной страницы. */
    fun forPage(chapterId: Long, pageIndex: Int): List<OcrScreenshotEntry> =
        _entries.value.filter { it.chapterId == chapterId && it.pageIndex == pageIndex }

    /** Очистить буфер. */
    fun clear() {
        _entries.value.forEach { deleteImageFile(it) }
        _entries.value = emptyList()
        _lastEntry.value = null
        persist()
    }

    /** Очистить скриншоты одной главы. */
    fun clearChapter(chapterId: Long) {
        val (keep, remove) = _entries.value.partition { it.chapterId != chapterId }
        remove.forEach { deleteImageFile(it) }
        _entries.value = keep
        if (_lastEntry.value?.chapterId == chapterId) _lastEntry.value = null
        persist()
    }

    /** Текущее количество записей в буфере. */
    fun size(): Int = _entries.value.size

    /** Размер файлов скриншотов (JSON + JPEG-кадры) в байтах. */
    fun diskSizeBytes(): Long {
        val jsonSize = persistFile?.length() ?: 0L
        val imagesSize = _entries.value.sumOf { it.imagePath?.let { p -> runCatching { File(p).length() }.getOrDefault(0L) } ?: 0L }
        return jsonSize + imagesSize
    }

    // ---- Внутренние ----

    private fun deleteImageFile(entry: OcrScreenshotEntry) {
        entry.imagePath?.let { path ->
            runCatching { File(path).delete() }.onFailure {
                logcat(LogPriority.WARN, it) { "OcrScreenshotBuffer: delete image failed" }
            }
        }
    }

    private fun persist() {
        val file = persistFile ?: return
        val entries = _entries.value
        scope.launch {
            try {
                file.writeText(json.encodeToString(entries))
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "OcrScreenshotBuffer: persist failed" }
            }
        }
    }

    private fun load() {
        val file = persistFile ?: return
        if (!file.exists()) return
        try {
            val text = file.readText()
            if (text.isBlank()) return
            val loaded = json.decodeFromString<List<OcrScreenshotEntry>>(text)
            _entries.value = loaded
            _lastEntry.value = loaded.lastOrNull()
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "OcrScreenshotBuffer: load failed" }
        }
    }
}

