package eu.kanade.tachiyomi.data.tts

import mihon.domain.ocr.service.OcrPreferences

/**
 * Роль говорящего (персонаж) для озвучки.
 *
 * Полноценный словарь поверх прежних трёх слотов ♀/♂/🎙: роль связывает имя
 * или метки [markers] с голосом, полом, возрастом и модификаторами
 * питча/темпа. Имя приходит из разметки `{имя:Аки}`, пол — из `{ж}/{м}` или
 * пресета пользователя.
 *
 * Правила подбора, по убыванию приоритета:
 *  1. имя говорящего совпало с меткой роли (без учёта регистра, подстрока);
 *  2. имя совпало с [name];
 *  3. явный пол (male/female) совпал с [gender] роли (клавиши ♀/♂/🎙 и
 *     ручной режим);
 *  4. пол «auto» — первая роль запасного совпадения только по имени [name]
 *     даже без меток не выбирается (риск ложного срабатывания).
 *
 * Все модификаторы перемножаются с пресетами [VoicePreset], поэтому роль
 * «Старик» звучит ниже/медленнее без ручной звукорежиссуры.
 */
data class VoiceRole(
    val id: String,
    val name: String,
    val gender: String = "auto", // auto | male | female | neutral
    val age: String = "adult", // VoicePreset.Age.id
    val voice: String = "", // «пакет::имя», пусто = подбор по полу/возрасту
    val pitch: Float = 1.0f,
    val rate: Float = 1.0f,
    val markers: List<String> = emptyList(),
) {

    /** Совпадает ли роль с именем говорящего (`{имя:Аки}`). */
    fun matchesName(speakerName: String?): Boolean {
        if (speakerName.isNullOrBlank()) return false
        val name = speakerName.trim().lowercase()
        if (this.name.lowercase() == name) return true
        return markers.any { marker ->
            val m = marker.lowercase()
            m == name || name.contains(m) || m.contains(name)
        }
    }

    /** Совпадает ли роль с явным полом реплики. */
    fun matchesGender(roleGender: String?): Boolean {
        if (roleGender.isNullOrBlank()) return false
        if (gender == "auto") return false
        return roleGender.equals(gender, ignoreCase = true) || roleGender == "narrator"
    }

    companion object {
        const val GENDER_AUTO = "auto"
        const val GENDER_MALE = "male"
        const val GENDER_FEMALE = "female"
        const val GENDER_NEUTRAL = "neutral"
    }
}

/**
 * Доступ к словарю голосовых ролей: JSON хранится в настройках
 * ([OcrPreferences.voiceRoles]), читается при каждой озвучке — менять роли
 * можно без перезапуска приложения.
 */
object VoiceRoleDictionary {

    /**
     * Разбор строки JSON-массива ролей. Не зависит от org.json (в юнит-тестах
     * app-модуля org.json не замокан и бросает), поэтому полностью ручной.
     */
    fun parse(json: String): List<VoiceRole> {
        val trimmed = json.trim()
        if (trimmed.isEmpty()) return emptyList()
        return VoiceJson.parseObjects(trimmed).mapNotNull { obj ->
            val name = obj["name"].orEmpty()
            if (name.isBlank()) return@mapNotNull null
            val markers = VoiceJson.parseArrayTokens(obj["markers"].orEmpty())
            VoiceRole(
                id = obj["id"].orEmpty().ifBlank { name },
                name = name,
                gender = obj["gender"].orEmpty().ifBlank { VoiceRole.GENDER_AUTO },
                age = obj["age"].orEmpty().ifBlank { "adult" },
                voice = obj["voice"].orEmpty(),
                pitch = obj["pitch"]?.toFloatOrNull()?.takeIf { it > 0f } ?: 1.0f,
                rate = obj["rate"]?.toFloatOrNull()?.takeIf { it > 0f } ?: 1.0f,
                markers = markers,
            )
        }
    }

    /** Ручная JSON-сериализация массива ролей. */
    fun toJson(roles: List<VoiceRole>): String {
        val sb = StringBuilder("[")
        roles.forEachIndexed { idx, role ->
            if (idx > 0) sb.append(',')
            sb.append('{')
            sb.append("\"id\":\"").append(VoiceJson.jsonEscape(role.id)).append('"')
            sb.append(",\"name\":\"").append(VoiceJson.jsonEscape(role.name)).append('"')
            sb.append(",\"gender\":\"").append(VoiceJson.jsonEscape(role.gender)).append('"')
            sb.append(",\"age\":\"").append(VoiceJson.jsonEscape(role.age)).append('"')
            sb.append(",\"voice\":\"").append(VoiceJson.jsonEscape(role.voice)).append('"')
            sb.append(",\"pitch\":").append(role.pitch)
            sb.append(",\"rate\":").append(role.rate)
            sb.append(",\"markers\":[")
            role.markers.forEachIndexed { mi, marker ->
                if (mi > 0) sb.append(',')
                sb.append('"').append(VoiceJson.jsonEscape(marker)).append('"')
            }
            sb.append("]}")
        }
        sb.append(']')
        return sb.toString()
    }

    fun load(prefs: OcrPreferences): List<VoiceRole> = parse(prefs.voiceRoles().get())

    fun save(prefs: OcrPreferences, roles: List<VoiceRole>) {
        prefs.voiceRoles().set(toJson(roles))
    }

    /**
     * Находит роль для реплики. [speakerName] — из `{имя:…}` (приоритет),
     * [gender] — явный пол (`{ж}/{м}`, кнопки карточки, ручной режим).
     */
    fun resolve(
        roles: List<VoiceRole>,
        speakerName: String?,
        gender: String?,
    ): VoiceRole? {
        val named = roles.filter { it.name.isNotBlank() }
        if (speakerName != null) {
            named.firstOrNull { it.matchesName(speakerName) }?.let { return it }
        }
        if (gender != null && (gender.equals("male", true) || gender.equals("female", true))) {
            named.firstOrNull { it.matchesGender(gender) }?.let { return it }
        }
        return null
    }

    fun resolve(prefs: OcrPreferences, speakerName: String?, gender: String?): VoiceRole? =
        resolve(load(prefs), speakerName, gender)
}

package eu.kanade.tachiyomi.data.tts

import mihon.domain.ocr.service.OcrPreferences

/**
 * Правило интонации: узор текста → произношение этого предложения.
 *
 * Позволяет задать паузы и модификаторы питча/темпа для характерных фраз
 * («Что?!», шёпот, крик, внутренние монологи). Правило применяется к
 * КОНКРЕТНОМУ предложению (после деления текста на предложения), поэтому
 * ударение из всех правил словаря не «залипает» на всю реплику.
 *
 * [exact] = true — узор должен совпадать со всем предложением целиком
 * (без учёта регистра), иначе достаточно вхождения подстроки.
 */
data class VoiceIntonationRule(
    val pattern: String,
    val exact: Boolean = false,
    val pauseMs: Int = 0,
    val pitch: Float = 1.0f,
    val rate: Float = 1.0f,
    val enabled: Boolean = true,
) {
    fun matches(sentence: String): Boolean {
        if (!enabled || pattern.isBlank()) return false
        return if (exact) {
            sentence.equals(pattern.trim(), ignoreCase = true)
        } else {
            sentence.contains(pattern.trim(), ignoreCase = true)
        }
    }
}

/**
 * Доступ к словарю интонаций: JSON в настройках
 * ([OcrPreferences.voiceIntonations]). Первое подходящее правило выигрывает;
 * порядок в списке = приоритет.
 */
object VoiceIntonationDictionary {

    /**
     * Разбор строки JSON-массива правил. Ручной разбор (org.json в юнит-тестах
     * app-модуля не замокан) — см. [VoiceRoleDictionary.parse].
     */
    fun parse(json: String): List<VoiceIntonationRule> {
        val trimmed = json.trim()
        if (trimmed.isEmpty()) return emptyList()
        val objs = if (trimmed.startsWith("[")) {
            VoiceJson.parseObjects(trimmed)
        } else {
            VoiceJson.parseObject(trimmed).run { listOf(this) }
        }
        return objs.mapNotNull { obj ->
            val pattern = obj["pattern"].orEmpty().trim()
            if (pattern.isBlank()) return@mapNotNull null
            VoiceIntonationRule(
                pattern = pattern,
                exact = obj["exact"]?.equals("true", ignoreCase = true) == true,
                pauseMs = obj["pauseMs"]?.toIntOrNull()?.coerceIn(0, 10000) ?: 0,
                pitch = obj["pitch"]?.toFloatOrNull()?.takeIf { it > 0f } ?: 1.0f,
                rate = obj["rate"]?.toFloatOrNull()?.takeIf { it > 0f } ?: 1.0f,
                enabled = obj["enabled"]?.let { it != "false" } ?: true,
            )
        }
    }

    /** Ручная JSON-сериализация массива правил. */
    fun toJson(rules: List<VoiceIntonationRule>): String {
        val sb = StringBuilder("[")
        rules.forEachIndexed { idx, rule ->
            if (idx > 0) sb.append(',')
            sb.append('{')
            sb.append("\"pattern\":\"").append(VoiceJson.jsonEscape(rule.pattern)).append('"')
            sb.append(",\"exact\":").append(rule.exact)
            sb.append(",\"pauseMs\":").append(rule.pauseMs)
            sb.append(",\"pitch\":").append(rule.pitch)
            sb.append(",\"rate\":").append(rule.rate)
            sb.append(",\"enabled\":").append(rule.enabled)
            sb.append('}')
        }
        sb.append(']')
        return sb.toString()
    }

    fun load(prefs: OcrPreferences): List<VoiceIntonationRule> =
        parse(prefs.voiceIntonations().get())

    fun save(prefs: OcrPreferences, rules: List<VoiceIntonationRule>) {
        prefs.voiceIntonations().set(toJson(rules))
    }

    /** Первое правило, подошедшее под предложение, или null. */
    fun matchRule(rules: List<VoiceIntonationRule>, sentence: String): VoiceIntonationRule? =
        rules.firstOrNull { it.matches(sentence) }

    fun matchRule(prefs: OcrPreferences, sentence: String): VoiceIntonationRule? =
        matchRule(load(prefs), sentence)
}

package eu.kanade.tachiyomi.data.tts

import android.content.Context
import eu.kanade.tachiyomi.data.ai.DocExporter
import mihon.domain.ocr.model.OcrPageResult
import java.io.File

/**
 * Собирает распознанный текст главы в единый документ со спикерами.
 *
 * После фонового скана ([eu.kanade.tachiyomi.data.ocr.OcrChapterScanner]) каждая
 * страница кэшируется как [OcrPageResult]. Этот хелпер читает эти кэши,
 * приписывает говорящему пол/голос (через локальную морфологию [LocalSpeakerAi])
 * и отдаёт текст в виде страниц-блоков. Готовый документ можно сохранить как
 * TXT / Markdown, а также выгрузить в PDF или DOCX через существующий
 * [DocExporter] (тот самый, что уже делает PDF/DOCX для AI-чата).
 *
 * Формат «кто говорит»: если пол не определён, реплика идёт как есть; если
 * определён — перед текстом ставится `[Ж]` / `[М]` (голос женский/мужской).
 */
object ChapterOcrTranscript {

    data class PageBlock(
        val pageIndex: Int,
        val title: String,
        val lines: List<SpokenLine>,
    )

    data class SpokenLine(
        val text: String,
        val gender: String?, // "female" | "male" | null
        val narrator: Boolean,
    )

    /**
     * Построить блоки страниц из кэшированных результатов.
     *
     * @param pages результаты OCR по порядку страниц (пустые страницы допустимы —
     *              они будут отмечены как «нет текста», а не выброшены).
     */
    fun build(pages: List<OcrPageResult>, chapterName: String): List<PageBlock> {
        return pages.mapIndexed { index, page ->
            val lines = page.regions
                .map { it.text.trim() }
                .filter { it.isNotBlank() }
                .map { text ->
                    val g = LocalSpeakerAi.guessGenders(listOf(text)).firstOrNull()
                    SpokenLine(
                        text = text,
                        gender = g?.takeIf { it == "female" || it == "male" },
                        narrator = false,
                    )
                }
            PageBlock(
                pageIndex = page.pageIndex,
                title = "$chapterName — страница ${index + 1}",
                lines = lines,
            )
        }
    }

    /** Превращает блоки в читаемый Markdown (заголовок + реплики с [[Ж]]/[[М]]). */
    fun toMarkdown(blocks: List<PageBlock>, title: String): String {
        val sb = StringBuilder()
        sb.append("# $title\n\n")
        blocks.forEach { b ->
            sb.append("## ${b.title}\n\n")
            if (b.lines.isEmpty()) {
                sb.append("_(текст не распознан)_\n\n")
            } else {
                b.lines.forEach { line ->
                    val gender = when (line.gender) {
                        "female" -> "[Ж] "
                        "male" -> "[М] "
                        else -> ""
                    }
                    sb.append("- $gender${line.text}\n")
                }
                sb.append("\n")
            }
        }
        return sb.toString()
    }

    /** Превращает блоки в плоский TXT (просто реплики в порядке чтения). */
    fun toPlainText(blocks: List<PageBlock>, title: String): String {
        val sb = StringBuilder()
        sb.append(title).append("\n").append("=".repeat(title.length)).append("\n\n")
        blocks.forEachIndexed { index, b ->
            sb.append("[${index + 1}] ${b.title}\n")
            b.lines.forEach { line ->
                val gender = when (line.gender) {
                    "female" -> "[Ж] "
                    "male" -> "[М] "
                    else -> ""
                }
                sb.append("  $gender${line.text}\n")
            }
            if (b.lines.isEmpty()) sb.append("  (текст не распознан)\n")
            sb.append("\n")
        }
        return sb.toString()
    }

    /**
     * Сохранить документ в папку экспорта воркспейса.
     *
     * @param format "md" | "txt" | "pdf" | "docx"
     * @return созданный файл.
     */
    fun write(context: Context, blocks: List<PageBlock>, title: String, format: String): File {
        val safeTitle = title.replace(Regex("[^\\p{L}\\p{N} _-]"), "_").take(60)
        val fileName = "$safeTitle.${if (format == "markdown") "md" else format}"
        return when (format) {
            "pdf" -> {
                val items = blocks.map { b ->
                    DocExporter.Item(
                        title = b.title,
                        text = b.lines.joinToString("\n") {
                            val g = when (it.gender) {
                                "female" -> "[Ж] " else -> if (it.gender == "male") "[М] " else ""
                            }
                            g + it.text
                        }.ifBlank { "—" },
                        imagePath = null,
                    )
                }
                DocExporter.exportPdf(context, items, fileName)
            }
            "docx" -> {
                val items = blocks.map { b ->
                    DocExporter.Item(
                        title = b.title,
                        text = b.lines.joinToString("\n") {
                            val g = when (it.gender) {
                                "female" -> "[Ж] " else -> if (it.gender == "male") "[М] " else ""
                            }
                            g + it.text
                        }.ifBlank { "—" },
                        imagePath = null,
                    )
                }
                DocExporter.exportDocx(context, items, fileName)
            }
            else -> {
                // TXT и MD — простые текстовые файлы.
                val text = if (format == "md" || format == "markdown") toMarkdown(blocks, title) else toPlainText(blocks, title)
                File(eu.kanade.tachiyomi.data.ai.AiWorkspace.root(context), "export")
                    .apply { mkdirs() }
                    .let { dir ->
                        File(dir, fileName).apply { writeText(text, Charsets.UTF_8) }
                    }
            }
        }
    }
}

package eu.kanade.tachiyomi.data.tts

import android.content.Context
import android.speech.tts.TextToSpeech
import mihon.domain.ocr.service.OcrPreferences
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get

/**
 * Продвинутый резолвер голосов: 1 / 2 / 3 голоса.
 *
 * Запрос пользователя:
 *  - 1 голос — один нарратор (выбор муж/жен) озвучивает всё
 *  - 2 голоса — мужской и женский (локальный или онлайн) по полу реплики
 *  - 3 голоса — муж + жен + нарратор (отдельный выбор)
 *
 *Каждый из трёх слотов имеет свой движок:
 *  - `pref_voice_male_engine`  → male
 *  - `pref_voice_female_engine`→ female
 *  - `pref_voice_narrator_engine` → narrator
 *и свой голос внутри движка (`pref_voice_male`, `pref_voice_female`, `pref_voice_name` для нарратора).
 *
 * Логика [resolve] применяется в [TtsSpeaker.speakAs] и [AutoReadEngine].
 */
object VoiceModeResolver {

    enum class Mode(val id: String, val title: String, val desc: String) {
        SINGLE("single", "Один голос", "Весь текст — голосом нарратора"),
        DUAL("dual", "Два голоса", "Мужские реплики — мужским, женские — женским"),
        TRIPLE("triple", "Три голоса", "Муж + Жен + Нарратор (описания, ремарки)"),
        /** Много голосов: свой голос каждому персонажу одного пола в сцене. */
        MULTI("multi", "Много голосов", "Отдельный голос каждому персонажу одного пола"),
        ;

        companion object {
            fun fromId(id: String?): Mode = entries.firstOrNull { it.id == id } ?: DUAL
        }
    }

    data class ResolvedVoice(
        val gender: String, // male | female | narrator
        val engine: String, // system_tts | google_web | remote_tts | eleven_api
        val voiceName: String,
        val isLocal: Boolean,
        val isOnline: Boolean,
    )

    private fun prefs(): OcrPreferences = Injekt.get()

    fun currentMode(): Mode = Mode.fromId(prefs().voiceMode().get())

    fun narratorGender(): String = prefs().narratorGender().get().lowercase().let {
        when (it) {
            "male", "female" -> it
            else -> "female" // auto → female по умолчанию
        }
    }

    /**
     * Выбрать голос для реплики с учётом режима и пола, определённого
     * морфологией/AI (female/male/null).
     *
     * @param detectedGender пол реплики от RuMorph/AI: "female"|"male"|null
     * @param isNarration был ли текст помечен как нарратив (без кавычек, описания)
     */
    fun resolve(
        detectedGender: String?,
        isNarration: Boolean = false,
        speakerSlot: Int = 0,
    ): ResolvedVoice {
        val mode = currentMode()
        val p = prefs()

        return when (mode) {
            Mode.SINGLE -> {
                val g = narratorGender()
                val engine = p.voiceNarratorEngine().get().ifBlank { p.voiceEngine().get() }
                val name = when (g) {
                    "male" -> p.voiceMale().get().ifBlank { p.voiceName().get() }
                    else -> p.voiceFemale().get().ifBlank { p.voiceName().get() }
                }
ResolvedVoice(
                    gender = g,
                    engine = engine,
                    voiceName = name,
                    isLocal = engine == TtsSpeaker.ENGINE_SYSTEM || engine == TtsSpeaker.ENGINE_REMOTE,
                    isOnline = engine == TtsSpeaker.ENGINE_GOOGLE_WEB || engine == TtsSpeaker.ENGINE_EDGE_TTS,
                )
            }
            Mode.DUAL -> {
                val g = detectedGender ?: narratorGender()
                val isMale = g == "male"
                val engine = if (isMale) p.voiceMaleEngine().get() else p.voiceFemaleEngine().get()
                val fallbackEngine = p.voiceEngine().get()
                val effEngine = engine.ifBlank { fallbackEngine }
                val name = if (isMale) p.voiceMale().get() else p.voiceFemale().get()
                ResolvedVoice(
                    gender = g,
                    engine = effEngine.ifBlank { TtsSpeaker.ENGINE_SYSTEM },
                    voiceName = name,
                    isLocal = effEngine == TtsSpeaker.ENGINE_SYSTEM || effEngine == TtsSpeaker.ENGINE_REMOTE,
                    isOnline = effEngine == TtsSpeaker.ENGINE_GOOGLE_WEB || effEngine == TtsSpeaker.ENGINE_EDGE_TTS,
                )
            }
            Mode.TRIPLE -> {
                if (isNarration) {
                    val g = narratorGender()
                    val engine = p.voiceNarratorEngine().get().ifBlank { p.voiceEngine().get() }
                    val name = when (g) {
                        "male" -> p.voiceMale().get().ifBlank { p.voiceName().get() }
                        else -> p.voiceFemale().get().ifBlank { p.voiceName().get() }
                    }
                    ResolvedVoice(g, engine.ifBlank { TtsSpeaker.ENGINE_SYSTEM }, name, true, false)
                } else {
                    val g = detectedGender ?: "female"
                    val isMale = g == "male"
                    val engine = if (isMale) p.voiceMaleEngine().get() else p.voiceFemaleEngine().get()
                    val name = if (isMale) p.voiceMale().get() else p.voiceFemale().get()
                    ResolvedVoice(g, engine.ifBlank { TtsSpeaker.ENGINE_SYSTEM }, name, true, false)
                }
            }
            // Много голосов: по полу, как DUAL; отдельные слоты персонажам
            // назначаются в AutoReadEngine (speakerSlot), здесь voice тот же.
            Mode.MULTI -> {
                val g = detectedGender ?: narratorGender()
                val isMale = g == "male"
                val engine = if (isMale) p.voiceMaleEngine().get() else p.voiceFemaleEngine().get()
                val fallbackEngine = p.voiceEngine().get()
                val effEngine = engine.ifBlank { fallbackEngine }
                val name = if (isMale) p.voiceMale().get() else p.voiceFemale().get()
                ResolvedVoice(
                    gender = g,
                    engine = effEngine.ifBlank { TtsSpeaker.ENGINE_SYSTEM },
                    voiceName = name,
                    isLocal = effEngine == TtsSpeaker.ENGINE_SYSTEM || effEngine == TtsSpeaker.ENGINE_REMOTE,
                    isOnline = effEngine == TtsSpeaker.ENGINE_GOOGLE_WEB || effEngine == TtsSpeaker.ENGINE_EDGE_TTS,
                )
            }
        }
    }

    fun describeCurrent(): String {
        val mode = currentMode()
        val p = prefs()
        return when (mode) {
            Mode.SINGLE -> "Один голос: нарратор ${narratorGender()} (${p.voiceNarratorEngine().get().ifBlank { p.voiceEngine().get() }})"
            Mode.DUAL -> "Два голоса: муж (${p.voiceMaleEngine().get().ifBlank { "system_tts" }}) + жен (${p.voiceFemaleEngine().get().ifBlank { "system_tts" }})"
            Mode.TRIPLE -> "Три голоса: муж (${p.voiceMaleEngine().get()}) + жен (${p.voiceFemaleEngine().get()}) + нарратор ${narratorGender()} (${p.voiceNarratorEngine().get()})"
            Mode.MULTI -> "Много голосов: отдельный голос каждому персонажу одного пола"
        }
    }

    /**
     * Применить resolved-голос к TextToSpeech: setVoice + rate/pitch от VoicePreset.
     */
    fun applyToTts(
        tts: TextToSpeech?,
        resolved: ResolvedVoice,
        rate: Float,
        pitch: Float,
    ) {
        if (tts == null) return
        val kind = when (resolved.gender) {
            "male" -> VoiceKind.MALE
            "female" -> VoiceKind.FEMALE
            else -> VoiceKind.OTHER
        }
        val voice = VoiceHelper.pickFor(tts, kind, resolved.voiceName.takeIf { it.isNotBlank() }, "ru", null)
        if (voice != null) {
            runCatching { tts.voice = voice }
        }
        tts.setSpeechRate(rate)
        tts.setPitch(pitch)
    }
}

