                when {
                    error != null -> ToolResult(call.name, "ОШИБКА: $error", status = "error")
                    AiProviders.save(context, spec) -> ToolResult(
                        call.name,
                        "Провайдер «${spec.title}» (${spec.model} @ ${spec.baseUrl}) сохранён. " +
