    fun systemVoiceSpecs(context: Context): List<Pair<String, String>> {
        val app = context.applicationContext
        val specs = mutableListOf<Pair<String, String>>()
        val wanted = runCatching { prefs().systemTtsEngine().get() }.getOrDefault("").trim()
        runCatching {
            val ready = CountDownLatch(1)
            var tts: TextToSpeech? = null
            tts = if (wanted.isNotBlank()) {
                TextToSpeech(app, { ready.countDown() }, wanted)
            } else {
                TextToSpeech(app) { ready.countDown() }
            }
            ready.await(ENGINE_QUERY_TIMEOUT_MS, TimeUnit.MILLISECONDS)
            val pkg = wanted.ifBlank {
                runCatching { tts?.defaultEngine }.getOrNull().orEmpty()
            }
            tts?.voices
                ?.filter { it.name.isNotBlank() }
                ?.forEach { v ->
                    val locale = runCatching { v.locale?.toString().orEmpty() }.getOrDefault("")
                    val label = if (locale.isBlank()) v.name else "${v.name} • $locale"
                    // Без пакета спецификация остаётся «голос без движка»:
                    // [speakWithVoice] теперь такой разбирает и берёт движок
                    // по умолчанию, а не ищет пакет с именем голоса.
                    specs += label to if (pkg.isBlank()) v.name else "$pkg${SPEC_SEPARATOR}${v.name}"
                }
            runCatching { tts?.shutdown() }
        }.onFailure { error ->
            logcat(LogPriority.WARN, error) { "systemVoiceSpecs failed" }
        }
        return specs
    }

    /**
     * Озвучивает текст выбранным в настройках движком.
     * [onState] — колбэк true=началось / false=закончилось|ошибка.
     */
    fun speak(context: Context, text: String, onState: (Boolean) -> Unit = {}) {
        speakAs(context, text, gender = null, onState = onState)
    }

    /** v1.9.40: spec голоса роли («пакет::имя») из слотов настроек. */
    fun slotVoiceSpec(role: String): String? = runCatching {
        // Словарь голосовых ролей имеет приоритет над legacy-слотами:
        // роль из {имя:Аки} или кнопки ♀/♂ может быть описана там точнее.
        val dictVoice = VoiceRoleDictionary.load(prefs())
            .firstOrNull { it.matchesName(role) }
            ?.voice
            ?.takeIf { it.isNotBlank() }
        if (dictVoice != null) return@runCatching dictVoice
        val arr = org.json.JSONArray(prefs().voiceSlots().get())
        (0 until arr.length()).map { i -> arr.getJSONObject(i) }
            .firstOrNull { it.optString("role") == role }
            ?.optString("voice")
            ?.takeIf { it.isNotBlank() }
    }.getOrNull()

    /**
     * Разбор спецификации голоса «пакет::имя».
     *
     * Раньше [speakWithVoice] брал `substringBefore("::")`, а он для строки
     * БЕЗ разделителя возвращает строку целиком. Локальный голос (`ru-ru-x-dfc-local`)
     * в итоге уезжал в `TextToSpeech(app, …, "ru-ru-x-dfc-local")` — пакета с
     * таким именем нет, движок не поднимался, и голос молча не звучал.
     * Теперь пустой пакет означает «движок по умолчанию», и это единственный
     * способ отличить локальный голос от сетевого.
     */
    fun parseVoiceSpec(voiceSpec: String?): Pair<String, String> {
        val raw = voiceSpec?.trim().orEmpty()
        if (raw.isEmpty()) return "" to ""
        val sep = raw.indexOf(SPEC_SEPARATOR)
        if (sep <= 0) return "" to raw
        return raw.substring(0, sep).trim() to raw.substring(sep + SPEC_SEPARATOR.length).trim()
    }

    private const val SPEC_SEPARATOR = "::"

    /** Голос Edge TTS по имени, если это точно сетевой голос. */
    private fun isEdgeVoiceName(name: String): Boolean =
        name.endsWith("Neural", ignoreCase = true) ||
            name.startsWith("ru-", ignoreCase = true) ||
            name.startsWith("en-", ignoreCase = true)

    /**
     * v1.9.40: озвучка КОНКРЕТНЫМ голосом («пакет::имя») в обход ролей и ручного
     * режима: кнопки «Проба» у слотов и ♀/♂/🎙 на карточке распознанного текста.
     * spec пуст = обычный основной голос.
     */
    fun speakWithVoice(
        context: Context,
        text: String,
        voiceSpec: String?,
        onState: (Boolean) -> Unit = {},
    ) {
        if (voiceSpec.isNullOrBlank()) {
            speak(context, text, onState)
            return
        }
        stop()
        onStateChange = onState
        val spoken = SpeechMarkup.forSpeech(SpeechMarkup.strip(text))
        if (spoken.isBlank()) {
            markFailure(SpeakFailure.NONE)
            setSpeaking(false)
            return
        }
        markFailure(SpeakFailure.NONE)
        // Голос роли может быть онлайн-голосом Edge TTS (в т.ч. в смешанном
        // словаре «онлайн+оффлайн»): маршрутизируем в Edge, а не в системный.
        val (forcedPkg, voiceName) = parseVoiceSpec(voiceSpec)
        if (voiceName.isEmpty()) {
            markFailure(SpeakFailure.REJECTED, "Голос не указан: $voiceSpec")
            setSpeaking(false)
            return
        }
        val enginePref = prefs().voiceEngine().get()
        val phoneOnly = runCatching { prefs().voicePhoneOnly().get() }.getOrDefault(true)
        val edgePkg = forcedPkg.startsWith("edge", ignoreCase = true)
        val wantEdge = when {
            // Пакет в спецификации голоса — это осознанный выбор конкретного
            // движка («edge::…», «com.github…::…»): телефонный режим его не
            // отменяет, иначе проба звучала бы не тем голосом, что и чтение.
            forcedPkg.isNotBlank() -> edgePkg
            // Явно выбранный сетевой движок — тоже осознанный выбор. Имя вида
            // «ru-ru-…» без пакета — это ЛОКАЛЬНЫЙ голос Google TTS, уводить
            // его в сеть нельзя.
            eu.kanade.tachiyomi.data.voice.VoicePlugins.isOnlineEngineId(enginePref) ->
                enginePref == ENGINE_EDGE_TTS
            // Телефонный режим гасит автоподстановку сетевого голоса.
            phoneOnly -> false
            // Голос без пакета и с явно сетевым режимом: решает движок, а не
            // догадка по имени.
            else -> isEdgeVoiceName(voiceName) &&
                !prefs().systemTtsEngine().get().isNullOrBlank()
        }
        if (wantEdge) {
            speakWithEdgeVoice(context, text, voiceName, onState)
            return
        }
        ensureSystem(context, forcedPkg.ifBlank { null }) { engine ->
            if (engine == null) {
                markFailure(
                    SpeakFailure.NO_ENGINE,
                    "TTS-движок не инициализирован: ${forcedPkg.ifBlank { systemEnginePkg ?: "по умолчанию" }}",
                )
                setSpeaking(false)
                return@ensureSystem
            }
            runCatching {
                val p = prefs()
                engine.setSpeechRate(p.speechRate().get().coerceIn(0.5f, 2f))
                engine.setPitch(p.speechPitch().get().coerceIn(0.5f, 2f))
                val picked = engine.voices?.firstOrNull { it.name == voiceName }
                if (picked != null) {
                    engine.voice = picked
                    // Язык — из самого голоса, а не из жёсткого «ru»: локальный
                    // голос en-us с русским текстом speak() отклоняет.
                    runCatching {
                        engine.language = picked.locale ?: engine.defaultVoice?.locale
                    }
                } else {
                    markFailure(
                        SpeakFailure.REJECTED,
                        "Голоса «$voiceName» нет в движке ${systemEnginePkg ?: "по умолчанию"}",
                    )
                }
                val maxLen = HARD_UTTERANCE_LIMIT
                val parts = spoken.chunked(maxLen)
                val lastId = "ywv_" + (parts.size - 1)
                engine.setOnUtteranceProgressListener(
                    object : UtteranceProgressListener() {
                        override fun onStart(utteranceId: String?) {
                            if (utteranceId == "ywv_0") setSpeaking(true)
                        }

                        override fun onDone(utteranceId: String?) {
                            if (utteranceId == lastId) setSpeaking(false)
                        }

                        override fun onError(utteranceId: String?) = utteranceFailed("ошибка движка")
                        override fun onError(utteranceId: String?, errorCode: Int) =
                            utteranceFailed("движок отклонил текст ($errorCode)")
                    },
                )
                var spokenAny = false
                parts.forEachIndexed { i, part ->
                    val ok = engine.speak(part, TextToSpeech.QUEUE_ADD, null, "ywv_$i")
                    // speak() возвращает ERROR, а не бросает: без проверки
                    // голос «озвучивался» в молчание.
                    if (ok == TextToSpeech.SUCCESS) spokenAny = true
                }
                if (!spokenAny) {
                    markFailure(SpeakFailure.REJECTED, "Движок не принял текст голосом «$voiceName»")
                    setSpeaking(false)
                }
            }.onFailure { error ->
                logcat(LogPriority.WARN, error) { "speakWithVoice failed for $voiceName" }
                markFailure(SpeakFailure.REJECTED, error.message ?: error.javaClass.simpleName)
                setSpeaking(false)
            }
        }
    }

    /**
     * Озвучка текста под роль (кнопки ♀/♂/🎙 на карточке распознанного текста).
     * Если для роли настроен голос (словарь ролей / legacy-слоты) — он
     * используется напрямую и может быть онлайн (Edge TTS) или оффлайн
     * (системный) — «совмещение онлайн и оффлайн голосов». Если голос не
     * настроен — обычная озвучка с учётом пола роли (♀/♂ → разные пресеты).
     */
    fun speakRole(
        context: Context,
        text: String,
        role: String,
        onState: (Boolean) -> Unit = {},
    ) {
        val spec = slotVoiceSpec(role)
        if (spec != null) {
            speakWithVoice(context, text, spec, onState)
            return
        }
        val gender = when (role.lowercase()) {
            "female" -> "female"
            "male" -> "male"
            else -> null
        }
        speakAs(context, text, gender, onState = onState)
    }

    /**
     * Проговорить текст КОНКРЕТНЫМ онлайн-голосом Edge TTS (кнопки «Выбрать
     * голос» в списке выбора и роль-кнопки со смешанным словарём).
     */
    fun speakWithEdgeVoice(
        context: Context,
        text: String,
        voice: String,
        onState: (Boolean) -> Unit = {},
    ) {
        if (voice.isBlank()) {
            speak(context, text, onState)
            return
        }
        stop()
        onStateChange = onState
        val spoken = SpeechMarkup.forSpeech(SpeechMarkup.strip(text))
        if (spoken.isBlank()) {
            setSpeaking(false)
            return
        }
        speakEdgeTts(context, spoken, voice)
    }

    /**
     * Озвучка с учётом пола говорящего: gender = "female" | "male" | null.
     * Для системного движка используется соответствующий голос из пресетов
     * (Настройки озвучки → Женский голос / Мужской голос). Для веб-движка
     * пол недоступен (у Google Translate один голос на язык).
     */
    @JvmOverloads
    fun speakAs(
        context: Context,
        text: String,
        gender: String?,
        speakerSlot: Int = 0,
        onState: (Boolean) -> Unit = {},
    ) {
        stop()
        onStateChange = onState
        // Сброс причины отказа на каждую попытку: иначе авточтение видело бы
        // старую неудачу и останавливалось на заведомо рабочем движке.
        markFailure(SpeakFailure.NONE)
        // Служебная разметка ({1}{ж}, ÷) не должна попасть в синтез, даже
        // если вызывающий код забыл её снять.
        val spoken = SpeechMarkup.forSpeech(SpeechMarkup.strip(text))
        if (spoken.isBlank()) {
            setSpeaking(false)
            return
        }
        // Ручной режим перекрывает и явно переданный пол, и разметку:
        // читатель нажал кнопку и ждёт выбранный голос везде.
        val manual = runCatching {
            prefs().takeIf { it.manualVoiceMode().get() }
                ?.manualVoiceGender()?.get()?.takeIf { g -> g.isNotBlank() }
        }.getOrNull()
        val effectiveGender = manual ?: gender ?: SpeechMarkup.genderOf(text)
        val slot = if (speakerSlot != 0) speakerSlot else SpeechMarkup.speakerSlot(text)
// Имя говорящего ({имя:Аки}) нужно словарю голосовых ролей, чтобы
        // подобрать голос/питч/темп конкретного персонажа.
        val speakerName = SpeechMarkup.speakerName(text)
        // «Только голос телефона» (pref_voice_phone_only, по умолчанию
        // включено) убирает АВТОМАТИЧЕСКИЙ сетевой маршрут: без явного выбора
        // движка читаем голосом устройства. Явно выбранный читателем сетевой
        // движок — тоже выбор, и он побеждает: иначе голос, которого нет на
        // устройстве, пришлось бы «устанавливать», вместо того чтобы звучать.
        val phoneOnly = runCatching { prefs().voicePhoneOnly().get() }.getOrDefault(true)
        val online = isNetworkAvailable(context)
        val effective = eu.kanade.tachiyomi.data.voice.VoicePlugins.resolveSpeakEngine(
            engineId = prefs().voiceEngine().get(),

metadata.preview:
        phoneOnly = phoneOnly,
        online = online,
    )
    when (effective) {
        ENGINE_GOOGLE_WEB -> speakGoogleWeb(context, spoken)
        ENGINE_EDGE_TTS -> speakEdgeTts(context, spoken)
        ENGINE_ELEVENLABS -> speakElevenLabs(context, spoken)
        // legacy-значения pref_voice_engine со сборок с ONNX:
        // нейроголоса теперь живут на сервере, маршрутизируем туда же.
        ENGINE_REMOTE, "onnx_tts", "onnx" -> speakRemote(context, spoken, effectiveGender)
        else -> speakSystem(context, spoken, effectiveGender, slot, speakerName)
    }
}

fun stop() {
    currentJob?.cancel()
    currentJob = null
    runCatching { systemTts?.stop() }
    runCatching {
        mediaPlayer?.stop()

display.text:
        phoneOnly = phoneOnly,
        online = online,
    )
    when (effective) {
        ENGINE_GOOGLE_WEB -> speakGoogleWeb(context, spoken)
        ENGINE_EDGE_TTS -> speakEdgeTts(context, spoken)
        ENGINE_ELEVENLABS -> speakElevenLabs(context, spoken)
        // legacy-значения pref_voice_engine со сборок с ONNX:
        // нейроголоса теперь живут на сервере, маршрутизируем туда же.
        ENGINE_REMOTE, "onnx_tts", "onnx" -> speakRemote(context, spoken, effectiveGender)
        else -> speakSystem(context, spoken, effectiveGender, slot, speakerName)
    }
}

fun stop() {
    currentJob?.cancel()
    currentJob = null
    runCatching { systemTts?.stop() }
    runCatching {
        mediaPlayer?.stop()
        mediaPlayer?.release()
    }
    mediaPlayer = null
    setSpeaking(false)
}

private fun setSpeaking(value: Boolean) {
    isSpeaking = value
    onStateChange?.invoke(value)
}

/**
 * Сбой utterance: помечаем причину и снимаем флаг речи. Вызывается из
 * [android.speech.tts.UtteranceProgressListener.onError], поэтому не должен
 * бросать — обратный вызов движка оборачивать исключения нельзя.
 */
private fun utteranceFailed(detail: String) {
    markFailure(SpeakFailure.REJECTED, detail)
    runCatching { logcat(LogPriority.WARN) { "TTS utterance failed: $detail" } }
    setSpeaking(false)
}

/**
 * Есть ли на устройстве хоть один системный TTS-движок.
 *
 * Быстрая проверка через PackageManager: без защёлки на `TextToSpeech`
 * и без блокировки, поэтому годится для предварительной проверки перед
 * авточтением. Пустой список означает ровно одно: системным голосом
 * озвучить нечего, и читать дальше бессмысленно.
 */
fun systemEngineInstalled(context: Context): Boolean =
    eu.kanade.tachiyomi.data.voice.VoicePlugins.installedSystemEngines(context).isNotEmpty()

// region SYSTEM

private fun speakSystem(
    context: Context,
    text: String,
    gender: String? = null,
    speakerSlot: Int = 0,
    speakerName: String? = null,
) {
    val slotVoiceRaw = runCatching {
        val arr = org.json.JSONArray(prefs().voiceSlots().get())
        val roleKey = when (gender) { "male" -> "male"; "female" -> "female"; else -> "narrator" }
        (0 until arr.length()).firstOrNull { i -> arr.getJSONObject(i).optString("role") == roleKey }
            ?.let { i -> arr.getJSONObject(i).optString("voice") }.orEmpty()
    }.getOrDefault("")
    val savedRawVoice = runCatching { prefs().voiceName().get() }.getOrDefault("")
    // Словарь голосовых ролей подбирает роль по имени говорящего
    // ({имя:Аки}), затем по полу. Голос/питч/темп роли перекрывают
    // слоты и пресеты пола, которые работают только по полу.
    val role = VoiceRoleDictionary.resolve(prefs(), speakerName, gender)
    // ВАЖНО: роль может как задать точный голос, так и только
    // модификаторы; распознаём оба случая отдельно.
    val rolePitch = role?.pitch?.takeIf { it > 0f && it != 1f } ?: 1f
    val roleRate = role?.rate?.takeIf { it > 0f && it != 1f } ?: 1f
    val roleVoice = role?.voice?.takeIf { it.isNotBlank() }
    // v1.9.41: для обычной озвучки (без пола) ГЛАВНЫЙ голос из настроек важнее
    // слота 🎙 — раньше слот перебивал выбор, и голос «не активировался».
    val primaryRaw = roleVoice
        ?: if (gender == null) {
            savedRawVoice.ifBlank { slotVoiceRaw }
        } else {
            slotVoiceRaw.ifBlank { savedRawVoice }
        }
    val forcedPkg = (
        roleVoice?.takeIf { it.isNotBlank() && it.contains("::") }?.substringBefore("::")
            ?: primaryRaw.takeIf { it.isNotBlank() && it.contains("::") }?.substringBefore("::")
            ?: slotVoiceRaw.takeIf { it.isNotBlank() && it.contains("::") }?.substringBefore("::")
            ?: savedRawVoice.takeIf { it.contains("::") }?.substringBefore("::")
        )?.ifBlank { null }
    ensureSystem(context, forcedPkg) { engine ->
        if (engine == null) {
            // Движок не поднялся: onInit вернул не SUCCESS, конструктор
            // бросил исключение на удалённом/невалидном пакете или движок
            // завис в полуинициализированном состоянии. Дальше озвучивать
            // нечем — вызывающий обязан это показать, а не листать страницы.
            markFailure(
                SpeakFailure.NO_ENGINE,
                "TTS-движок не инициализирован: ${systemEnginePkg ?: "движок по умолчанию"}",
            )
            setSpeaking(false)
            return@ensureSystem
        }
        val p = prefs()
        // Пресет голоса пол/возраст: модификаторы питча и темпа.
        val presetAge = VoicePreset.Age.fromId(p.voicePresetAge().get())
        val presetGender = VoicePreset.Gender3.fromId(p.voicePresetGender().get())
        engine.setSpeechRate((p.speechRate().get() * presetAge.rate).coerceIn(0.5f, 2f))
        engine.setPitch(p.speechPitch().get().coerceIn(0.5f, 2f))
        // Пол говорящего (логика из overlay-translator):
        // 1) явный пресет пользователя для пола; 2) VoiceHelper.pick —
        // автоподбор по классификации имён (Svetlana/Dmitry/детские);
        // 3) общий голос; 4) язык ru-RU как последний рубеж.
        // Совет локального JSON-помощника (правила пользователя/агента)
        val advisorVoice = primaryRaw.substringAfterLast("::").ifBlank { LocalVoiceAdvisor.recommend(text, gender).voiceName }
        val presetVoice = advisorVoice ?: when (gender) {
            "female" -> p.voiceFemale().get()
            "male" -> p.voiceMale().get()
            else -> ""
        }
        val kind = when (gender) {
            "male" -> VoiceKind.MALE
            "female" -> VoiceKind.FEMALE
            else -> when (presetGender) {
                VoicePreset.Gender3.MALE -> VoiceKind.MALE
                VoicePreset.Gender3.FEMALE -> VoiceKind.FEMALE
                else -> null
            }
        }
        // Разные персонажи одного пола получают разные голоса: слот > 0
        // сдвигает выбор внутри группы. Явный пресет пользователя всегда
        // важнее автоподбора.
        val activeEnginePackage = systemEnginePkg
            ?: runCatching { engine.defaultEngine }.getOrNull()
        val isRhVoice = activeEnginePackage.orEmpty().contains("rhvoice", ignoreCase = true)
        var chosen: android.speech.tts.Voice? = when {
            presetVoice.isNotBlank() && speakerSlot == 0 ->
                VoiceHelper.pick(
                    engine,
                    kind ?: VoiceKind.FEMALE,
                    presetVoice,
                    systemEnginePkg,
                )
            kind != null && speakerSlot > 0 ->
                VoiceHelper.pickForSpeaker(
                    engine,
                    kind,
                    speakerSlot,
                    enginePackage = systemEnginePkg,
                ) ?: VoiceHelper.pick(engine, kind, null, systemEnginePkg)
            kind != null -> VoiceHelper.pick(engine, kind, null, systemEnginePkg)
            else -> {
                val saved = p.voiceName().get().substringAfterLast("::")
                // Автоподбор как в overlay-translator: если голос не выбран
                // или его нет в системе — берём лучший русский женский
                // (Svetlana и др.), затем любой русский.
                VoiceHelper.pick(engine, VoiceKind.FEMALE, saved, systemEnginePkg)
            }
        }
        // RHVoice на части прошивок отдаёт пустой getVoices(): клиент «не
        // видит» установленные голоса, pick() соскальзывал на дефолт движка
        // (почти всегда женский), и все роли звучали одним голосом. Сам же
        // сервис RHVoice принимает точное имя и через setVoice(), и через
        // параметр "voiceName" в speak() — поэтому Voice создаётся руками
        // и выбор пользователя больше не теряется.
        if (isRhVoice && presetVoice.isNotBlank() && speakerSlot == 0 &&
            (chosen == null || chosen.name != presetVoice)
        ) {
            chosen = runCatching {
                android.speech.tts.Voice(
                    presetVoice,
                    Locale("ru", "RU"),
                    android.speech.tts.Voice.QUALITY_NORMAL,
                    0,
                    false,
                    null,
                )
            }.getOrNull() ?: chosen
        }
        val v = chosen
        val forcedVoiceName = when {
            isRhVoice && presetVoice.isNotBlank() && speakerSlot == 0 -> presetVoice
            isRhVoice -> v?.name
            else -> null
        }
        if (v != null) {
            val res = engine.setVoice(v)
            if (res != TextToSpeech.SUCCESS) {
                // Some OEM clients reject a manually-created RHVoice Voice
                // before the engine sees it. speak() below also sends the
                // exact name in KEY_PARAM_VOICE_NAME, bypassing that bug.
                logcat(LogPriority.WARN) { "Voice ${v.name} rejected by TextToSpeech client" }
                engine.language = v.locale ?: Locale("ru", "RU")
            }
        } else {
            // Язык движка по умолчанию, а не жёсткий ru: иначе локальный
            // en-us голос получает русский текст и speak() отклоняет его.
            engine.language = engine.defaultVoice?.locale ?: Locale("ru", "RU")
        }
        // v1.9.44: hidden-параметр «voiceName» убран: движки (RHVoice на
        // устройстве) ОТКЛОНЯЮТ speak() с таким Bundle — пресеты Ж/М/нарратор
        // звучали тишиной. Голос уже поставлен через setVoice() выше.
        val voiceParams: android.os.Bundle? = null
        // Пунктуация → реальные паузы и интонация: текст режется на
        // предложения, каждое говорится отдельной utterance, между ними
        // тишина (250мс после точки, 420мс после !/?, 160мс после запятой).
        // Вопросительные получают лёгкий подъём питча, восклицательные —
        // чуть быстрее и выше.
        // Ударения для локальных голосов: RHVoice понимает «+» после
        // ударного гласного; прочие движки получают исходный текст.
        val spokenText = if (isRhVoice && prefs().ruStress().get() == "on") {
            RuStress.mark(text)
        } else {
            text
        }
        val sentences = splitSentences(spokenText)
        if (sentences.isEmpty()) { setSpeaking(false); return@ensureSystem }
        // Предложение может распасться на несколько кусков: звук из
        // ремарки и «ааа» произносятся отдельно от остального текста, со
        // своей подачей. Плоский список нужен ещё и для того, чтобы
        // `lastId` указывал на последний utterance, а не на последнее
        // предложение.
        val units = mutableListOf<TtsUnit>()
        for (sentence in sentences) {
            val trimmed = sentence.trim()
            if (trimmed.isEmpty()) continue
            // Словарь интонаций: узор фразы → пауза/питч/темп. Правило
            // ищется по всему предложению и умножается на все его куски,
            // иначе «Ааа! Прости...» не нашло бы узор по целой фразе.
            val intonation = VoiceIntonationDictionary.matchRule(p, trimmed)
            val intonationPitch = intonation?.pitch?.takeIf { it > 0f && it != 1f } ?: 1f
            val intonationRate = intonation?.rate?.takeIf { it > 0f && it != 1f } ?: 1f
            val intonationPause = intonation?.pauseMs?.takeIf { it > 0 } ?: 0
            for (d in SpeechCue.deliveries(trimmed)) {
                units += TtsUnit(d, intonationPitch, intonationRate, intonationPause)
            }
        }
        if (units.isEmpty()) { setSpeaking(false); return@ensureSystem }
        val lastId = "yk_${units.size - 1}"
        engine.setOnUtteranceProgressListener(object : UtteranceProgressListener() {
            override fun onStart(utteranceId: String?) {
                if (utteranceId == "yk_0") setSpeaking(true)
            }
            override fun onDone(utteranceId: String?) {
                if (utteranceId == lastId) setSpeaking(false)
            }
            // onError идёт в том же Boolean-колбэке, что и onDone, поэтому
            // сбой посреди фразы выглядел как успех: в журнал попадало
            // «озвучено», а голоса не было. Причину отказа помечаем явно.
            @Deprecated("Deprecated in Java")
            override fun onError(utteranceId: String?) = utteranceFailed("движок прервал озвучку")
            override fun onError(utteranceId: String?, errorCode: Int) =
                utteranceFailed("движок вернул ошибку $errorCode")
        })
        val baseRate = (p.speechRate().get() * presetAge.rate * roleRate).coerceIn(0.5f, 2f)
        // Тон по полу: если для пола не нашлось ОТДЕЛЬНОГО голоса,
        // различаем персонажей питчем — мужчины ниже, женщины выше.
        // С отдельными голосами модификатор не нужен (=1.0). Роль из
        // словаря добавляет свой pitch/rate поверх всех пресетов.
        val voiceMatchesGender = v != null && when (gender) {
            "male" -> VoiceHelper.classify(v) == VoiceKind.MALE
            "female" -> VoiceHelper.classify(v) == VoiceKind.FEMALE
            else -> true
        }
        val genderPitchMod = when {
            voiceMatchesGender -> 1.0f
            gender == "male" -> 0.78f
            gender == "female" -> 1.18f
            else -> 1.0f
        }
        val basePitch = (p.speechPitch().get() * genderPitchMod *
            presetGender.pitch * presetAge.pitch * rolePitch).coerceIn(0.5f, 2f)
        var queued = false
        units.forEachIndexed { i, unit ->
            val trimmed = unit.delivery.text.trim()
            if (trimmed.isEmpty()) return@forEachIndexed
            val cue = unit.delivery
            when {
                // Звук из ремарки или междометие: подача уже задана, знаки
                // препинания поверх неё не добавляются — иначе «Ааа!»
                // получил бы крик дважды.
                cue.fromCue || unit.intonationPitch != 1f || unit.intonationRate != 1f -> {
                    engine.setPitch((basePitch * unit.intonationPitch * cue.pitch).coerceIn(0.5f, 2f))
                    engine.setSpeechRate((baseRate * unit.intonationRate * cue.rate).coerceIn(0.5f, 2f))
                }
                trimmed.endsWith("?") || trimmed.endsWith("?!") || trimmed.endsWith("⁇") -> {
                    engine.setPitch((basePitch * 1.12f).coerceAtMost(2f))
                    engine.setSpeechRate(baseRate * 0.95f)
                }
                trimmed.endsWith("!") || trimmed.endsWith("‼") -> {
                    engine.setPitch((basePitch * 1.07f).coerceAtMost(2f))
                    engine.setSpeechRate((baseRate * 1.05f).coerceAtMost(2f))
                }
                else -> {
                    // Состояние из ремарки (шёпот, бег, слабость) — это
                    // множитель всей реплики, а не отдельного слова.
                    engine.setPitch((basePitch * cue.pitch).coerceIn(0.5f, 2f))
                    engine.setSpeechRate((baseRate * cue.rate).coerceIn(0.5f, 2f))
                }
            }
            val mode = if (queued) TextToSpeech.QUEUE_ADD else TextToSpeech.QUEUE_FLUSH
            val r = try {
                engine.speak(trimmed, mode, voiceParams, "yk_$i")
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "speak() rejected an utterance" }
                TextToSpeech.ERROR
            }
            if (r == TextToSpeech.SUCCESS) queued = true
            val pauseMs = when {
                // Сначала словарь интонаций, затем ремарка: её пауза
                // относится к конкретному куску, а не ко всей фразе.
                unit.intonationPause > 0 -> unit.intonationPause.toLong()
                cue.pauseAfterMs > 0 -> cue.pauseAfterMs.toLong()
                trimmed.endsWith("!") || trimmed.endsWith("?") ||
                    trimmed.endsWith("‼") || trimmed.endsWith("⁇") -> 420L
                trimmed.endsWith(",") || trimmed.endsWith(";") -> 160L
                else -> 260L
            }
            runCatching {
                engine.playSilentUtterance(pauseMs, TextToSpeech.QUEUE_ADD, "yk_p$i")
            }
        }
        if (!queued) {
            markFailure(SpeakFailure.REJECTED, "движок не принял ни одной фразы")
            setSpeaking(false)
        }
    }
}

package eu.kanade.tachiyomi.data.ai

import android.content.Context
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.delay
import kotlinx.coroutines.withContext
import logcat.LogPriority
import mihon.domain.ocr.service.OcrPreferences
import org.json.JSONArray
import org.json.JSONObject
import tachiyomi.core.common.util.system.logcat
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get
import java.io.File
import java.net.HttpURLConnection
import java.net.URL
import java.util.zip.ZipInputStream

/**
 * ПОЛУ-ОНЛАЙН LLM: GGUF/большие модели исполняются НЕ на телефоне, а на
 * GitHub Actions ранере (workflow llm-runner.yml):
 *  1) приложение по PAT-токену диспатчит workflow с выбранной моделью и
 *     случайным id сессии;
 *  2) ранер скачивает GGUF, поднимает llama.cpp server + cloudflared-туннель
 *     и публикует артефакт endpoint-<session> c URL и ключом сессии;
 *  3) приложение опрашивает артефакты, забирает endpoint и дальше говорит с
 *     моделью напрямую (OpenAI-совместимый /v1/chat/completions).
 *
 * Каждая сессия сохраняется НА ТЕЛЕФОНЕ (files/llm_sessions/<session>.json):
 * URL, ключ, модель, история сообщений — при перезапуске приложения диалог
 * продолжается без потери контекста, пока жив ранер (до ~5.5 часов).
 */
object RunnerLlm {

    data class Session(
        val id: String,
        val model: String,
        var url: String? = null,
        var apiKey: String? = null,
        /** Веб-терминал ранера (ttyd): живые логи llama-server + shell. */
        var terminalUrl: String? = null,
        /** ОС ранера: linux | windows. */
        var os: String = "linux",
        val messages: MutableList<Pair<String, String>> = mutableListOf(), // role -> content
        var createdAt: Long = System.currentTimeMillis(),
    )

    /** key -> (описание, ТОЧНЫЙ размер скачивания в ранер, МБ — проверено HEAD). */
    val GGUF_MODELS = listOf(
        Triple("qwen2.5-0.5b", "Qwen2.5 0.5B (GGUF Q4) — самый быстрый старт", 468),
        Triple("qwen2.5-1.5b", "Qwen2.5 1.5B (GGUF Q4) — лучший русский", 1065),
        Triple("llama3.2-1b", "Llama 3.2 1B (GGUF Q4) — английский", 770),
        Triple("gemma3-1b", "Gemma 3 1B (GGUF Q4) — компактная от Google", 768),
    )

    private const val REPO = "sj0404-collab/yomikai"
    private const val WORKFLOW = "llm-runner.yml"
    private const val WORKFLOW_OPENCODE = "opencode.yml"
    private const val WORKFLOW_VIDEO = "video-runner.yml"
    // Графика opencode.yml живёт в main (GitHub диспатчит только воркфлоу из
    // default-ветки), а agent/, npm-hub/, tools/ — в ветке prototype-opencode-agent,
    // которую воркфлоу чекаутит первым шагом.
    private const val OPENCODE_REF = "main"

    private fun prefs(): OcrPreferences = Injekt.get()

    private fun sessionsDir(context: Context): File =
        File(context.filesDir, "llm_sessions").apply { mkdirs() }

    fun listSessions(context: Context): List<Session> =
        sessionsDir(context).listFiles { f -> f.extension == "json" }
            ?.mapNotNull { runCatching { fromJson(JSONObject(it.readText())) }.getOrNull() }
            ?.sortedByDescending { it.createdAt }
            .orEmpty()

    fun saveSession(context: Context, s: Session) {
        File(sessionsDir(context), "${s.id}.json").writeText(toJson(s).toString())
    }

    fun deleteSession(context: Context, s: Session) {
        File(sessionsDir(context), "${s.id}.json").delete()
    }

    private fun toJson(s: Session) = JSONObject()
        .put("id", s.id).put("model", s.model).put("url", s.url ?: "")
        .put("apiKey", s.apiKey ?: "").put("createdAt", s.createdAt)
        .put("terminalUrl", s.terminalUrl ?: "")
        .put("os", s.os)
        .put(
            "messages",
            JSONArray().apply {
                s.messages.forEach { (r, c) -> put(JSONObject().put("role", r).put("content", c)) }
            },
        )

    private fun fromJson(j: JSONObject) = Session(
        id = j.getString("id"),
        model = j.getString("model"),
        url = j.optString("url").ifBlank { null },
        apiKey = j.optString("apiKey").ifBlank { null },
        terminalUrl = j.optString("terminalUrl").ifBlank { null },
        os = j.optString("os").ifBlank { "linux" },
        createdAt = j.optLong("createdAt"),
        messages = mutableListOf<Pair<String, String>>().apply {
            val arr = j.optJSONArray("messages") ?: JSONArray()
            for (i in 0 until arr.length()) {
                val m = arr.getJSONObject(i)
                add(m.getString("role") to m.getString("content"))
            }
        },
    )

    /**
     * Запуск новой сессии: dispatch workflow → ожидание артефакта endpoint
     * (обычно 2-4 минуты: скачивание модели в ранер). [onStatus] — живые
     * статусы для UI. null при ошибке/отсутствии токена.
     */
    suspend fun startSession(
        context: Context,
        modelKey: String,
        onStatus: (String) -> Unit,
        os: String = "linux",
    ): Session? = startSessionInternal(context, modelKey, "", onStatus, os)

    private suspend fun startSessionInternal(
        context: Context,
        modelKey: String,
        customUrl: String,
        onStatus: (String) -> Unit,
        os: String = "linux",
    ): Session? = withContext(Dispatchers.IO) {
        val token = prefs().githubPat().get()
        if (token.isBlank()) {
            onStatus("Нет GitHub-токена: задайте его в настройках вкладки AI (⚙)")
            return@withContext null
        }
        val selectedOs = if (os == "windows") "windows" else "linux"
        val session = Session(
            id = "s" + System.currentTimeMillis().toString(36) + (1000..9999).random(),
            model = modelKey,
            os = selectedOs,
        )

        onStatus("Отправляем запуск в GitHub Actions…")
        val dispatchBody = JSONObject()
            .put("ref", "main")
            .put(
                "inputs",
                JSONObject()
                    .put("model", modelKey)
                    .put("session", session.id)
                    .put("custom_url", customUrl)
                    .put("os", selectedOs),
            )
        val dispatch = runCatching {
            githubRequest(
                token = token,
                url = "https://api.github.com/repos/$REPO/actions/workflows/$WORKFLOW/dispatches",
                method = "POST",
                body = dispatchBody.toString(),
            )
        }.getOrElse {
            onStatus("Не удалось связаться с GitHub: ${it.message ?: "ошибка сети"}")
            return@withContext null
        }
        if (dispatch.code !in 200..299) {
            onStatus("GitHub отклонил запуск (${dispatch.code}): ${apiError(dispatch.body)}")
            return@withContext null
        }

        // Workflow dispatch не возвращает id запуска. Находим ровно наш run по
        // уникальному session id, затем читаем только ЕГО job и артефакты.
        // Это устраняет гонку старой реализации с глобальными 20 артефактами.
        val deadline = System.currentTimeMillis() + START_TIMEOUT_MS
        var lastStatus = ""
        var runId: Long? = null
        while (System.currentTimeMillis() < deadline) {
            val state = fetchRunState(token, session.id, selectedOs)
            runId = state.runId ?: runId
            if (state.message != lastStatus) {
                onStatus(state.message)
                lastStatus = state.message
            }

            // Endpoint публикуется до долгого keep-alive шага. Ищем его в
            // конкретном run, поэтому параллельные ранеры больше не мешают.
            runId?.let { id ->
                fetchEndpointArtifact(token, id, session.id)?.let { endpoint ->
                    session.url = endpoint.first
                    session.apiKey = endpoint.second
                    session.terminalUrl = endpoint.third.ifBlank { null }
                    saveSession(context, session)
                    onStatus("✅ Сессия готова: ${endpoint.first}")
                    return@withContext session
                }
            }

            // Раньше failure/cancelled молча проглатывались, и приложение все
            // восемь минут показывало ожидание. Теперь ошибка шага видна сразу.
            if (state.terminal) {
                onStatus(state.message)
                return@withContext null
            }
            delay(POLL_INTERVAL_MS)
        }
        onStatus(
            if (runId == null) {
                "Таймаут: GitHub не создал запуск за ${START_TIMEOUT_MS / 60_000} минут"
            } else {
                "Таймаут: endpoint не появился за ${START_TIMEOUT_MS / 60_000} минут. " +
                    "Последний статус: ${lastStatus.ifBlank { "неизвестен" }}"
            },
        )
        null
    }

    //
    // Генерация видео (video-runner.yml)
    //

    data class VideoRequest(
        /** "text" — текстовая анимация; "slideshow" — из готовых картинок. */
        val mode: String = "text",
        /** Заголовок/капшн, рисуется поверх кадров. */
        val text: String = "",
        /** URL картинок для слайд-шоу (pollinations и т.п.). */
        val images: List<String> = emptyList(),
        val fps: Int = 3,
    )

    data class VideoResult(val file: File, val sizeBytes: Long)

    /**
     * Генерация видео НА РАНЕРЕ: диспатчим video-runner.yml, ждём артефакта
     * video-<session> и скачиваем mp4. Python + ffmpeg на ubuntu-раннере не
     * исполняют произвольный код из запроса — текст только рисуется на кадрах,
     * картинки скачиваются по URL.
     */
    suspend fun startVideo(
        context: Context,
        request: VideoRequest,
        onStatus: (String) -> Unit,
    ): VideoResult? = withContext(Dispatchers.IO) {
        val token = prefs().githubPat().get()
        if (token.isBlank()) {
            onStatus("Нет GitHub-токена: задайте PAT в настройках вкладки AI (⚙)")
            return@withContext null
        }
        val session = "v" + System.currentTimeMillis().toString(36) + (1000..9999).random()

        onStatus("Отправляем генерацию видео в GitHub Actions…")
        val dispatchBody = JSONObject()
            .put("ref", "main")
            .put(
                "inputs",
                JSONObject()
                    .put("session", session)
                    .put("mode", if (request.mode == "slideshow") "slideshow" else "text")
                    .put("text", request.text)
                    .put("images", JSONArray(request.images))
                    .put("fps", request.fps.coerceIn(1, 24)),
            )
        val dispatch = runCatching {
            githubRequest(
                token = token,
                url = "https://api.github.com/repos/$REPO/actions/workflows/$WORKFLOW_VIDEO/dispatches",
                method = "POST",
                body = dispatchBody.toString(),
            )
        }.getOrElse {
            onStatus("Не удалось связаться с GitHub: ${it.message ?: "ошибка сети"}")
            return@withContext null
        }
        if (dispatch.code !in 200..299) {
            onStatus("GitHub отклонил запуск (${dispatch.code}): ${apiError(dispatch.body)}")
            return@withContext null
        }

        val deadline = System.currentTimeMillis() + VIDEO_TIMEOUT_MS
        var lastStatus = ""
        var runId: Long? = null
        while (System.currentTimeMillis() < deadline) {
            val state = fetchRunState(
                token, session, "linux",
                workflow = WORKFLOW_VIDEO, stepText = ::videoStepText,
            )
            runId = state.runId ?: runId
            if (state.message != lastStatus) {
                onStatus(state.message)
                lastStatus = state.message
            }

            runId?.let { id ->
                fetchVideoArtifact(token, id, session)?.let { result ->
                    onStatus("✅ Видео готово: ${result.sizeBytes / 1024} КБ")
                    return@withContext result
                }
            }

            if (state.terminal) {
                onStatus(state.message)
                return@withContext null
            }
            delay(POLL_INTERVAL_MS)
        }
        onStatus(
            if (runId == null) {
                "Таймаут: GitHub не создал запуск за ${VIDEO_TIMEOUT_MS / 60_000} минут"
            } else {
                "Таймаут: видео не появилось за ${VIDEO_TIMEOUT_MS / 60_000} минут. " +
                    "Последний статус: ${lastStatus.ifBlank { "неизвестен" }}"
            },
        )
        null
    }

    private const val VIDEO_TIMEOUT_MS = 9L * 60_000L

    /** Человекочитаемые статусы этапов video-runner.yml. */
    private fun videoStepText(name: String): String? = when {
        name.startsWith("Setup Python") -> "Готовим Python на ранере…"
        name.startsWith("Create renderer") -> "Собираем генератор кадров…"
        name.startsWith("Render frames") -> "Рисуем кадры видео…"
        name.startsWith("Encode video") -> "Сжимаем видео…"
        name.startsWith("Upload video") -> "Загружаем готовое видео…"
        else -> null
    }

    /** Скачать артефакт video-<session> и вернуть первый mp4 внутри. */
    private fun fetchVideoArtifact(token: String, runId: Long, sessionId: String): VideoResult? {
        return runCatching {
            val response = githubRequest(
                token,
                "https://api.github.com/repos/$REPO/actions/runs/$runId/artifacts?per_page=100",
            )
            if (response.code !in 200..299) return null
            val artifacts = JSONObject(response.body).getJSONArray("artifacts")
            var downloadUrl: String? = null
            for (i in 0 until artifacts.length()) {
                val artifact = artifacts.getJSONObject(i)
                if (
                    artifact.getString("name") == "video-$sessionId" &&
                    !artifact.getBoolean("expired")
                ) {
                    downloadUrl = artifact.getString("archive_download_url")
                    break
                }
            }
            val url = downloadUrl ?: return null
            val zip = githubDownload(token, url)
            if (zip.code !in 200..299 || zip.body.isEmpty()) return null
            var out: File? = null
            ZipInputStream(zip.body.inputStream()).use { zis ->
                var entry = zis.nextEntry
                while (entry != null) {
                    if (!entry.isDirectory && entry.name.endsWith(".mp4")) {
                        val bytes = zis.readBytes()
                        if (bytes.size >= 1024) {
                            out = File.createTempFile("yomi_video_", ".mp4")
                                .apply { writeBytes(bytes) }
                            break
                        }
                    }
                    entry = zis.nextEntry
                }
            }
            out?.let { VideoResult(it, it.length()) }
        }.getOrNull()
    }

    private const val START_TIMEOUT_MS = 12L * 60_000L
    private const val POLL_INTERVAL_MS = 5_000L

    private data class GithubResponse(val code: Int, val body: String)

    private data class BinaryResponse(val code: Int, val body: ByteArray)

    private data class RunState(
        val runId: Long? = null,
        val terminal: Boolean = false,
        val message: String,
    )

    /**
     * GET/POST GitHub API с таймаутами и чтением тела ошибки.
     * Ходит через прокси приложения (Настройки → Сеть), как и AI-чат:
     * раньше раннеры молча игнорировали прокси и не работали там, где
     * прямой доступ к api.github.com заблокирован.
     */
    private fun githubRequest(
        token: String,
        url: String,
        method: String = "GET",
        body: String? = null,
    ): GithubResponse {
        val conn = AiAssistant.openConnection(url) as HttpURLConnection
        try {
            conn.requestMethod = method
            conn.connectTimeout = 15_000
            conn.readTimeout = 30_000
            conn.setRequestProperty("Authorization", "Bearer $token")
            conn.setRequestProperty("Accept", "application/vnd.github+json")
            conn.setRequestProperty("X-GitHub-Api-Version", "2022-11-28")
            conn.setRequestProperty("User-Agent", "Yomihon-Runner")
            if (body != null) {
                conn.doOutput = true
                conn.setRequestProperty("Content-Type", "application/json; charset=utf-8")
                conn.outputStream.use { it.write(body.toByteArray()) }
            }
            val code = conn.responseCode
            val stream = if (code in 200..299) conn.inputStream else conn.errorStream
            return GithubResponse(code, stream?.use { it.readBytes().toString(Charsets.UTF_8) }.orEmpty())
        } finally {
            conn.disconnect()
        }
    }

    /** Скачивание бинарного артефакта с безопасным проходом GitHub redirect. */
    private fun githubDownload(token: String, initialUrl: String): BinaryResponse {
        var currentUrl = initialUrl
        repeat(5) {
            val url = URL(currentUrl)
            // Redirects ведут на внешнее хранилище артефактов — напрямую, без прокси.
            val viaProxy = url.host == "api.github.com"
            val conn = if (viaProxy) {
                AiAssistant.openConnection(currentUrl) as HttpURLConnection
            } else {
                url.openConnection() as HttpURLConnection
            }
            try {
                conn.instanceFollowRedirects = false
                conn.connectTimeout = 15_000
                conn.readTimeout = 30_000
                conn.setRequestProperty("Accept", "application/vnd.github+json")
                conn.setRequestProperty("User-Agent", "Yomihon-Runner")
                // Не отправляем PAT на внешний release-assets/blob storage.
                if (url.host == "api.github.com") {
                    conn.setRequestProperty("Authorization", "Bearer $token")
                    conn.setRequestProperty("X-GitHub-Api-Version", "2022-11-28")
                }
                val code = conn.responseCode
                if (code in setOf(301, 302, 303, 307, 308)) {
                    currentUrl = conn.getHeaderField("Location")
                        ?: return BinaryResponse(code, ByteArray(0))
                } else {
                    val stream = if (code in 200..299) conn.inputStream else conn.errorStream
                    return BinaryResponse(code, stream?.use { it.readBytes() } ?: ByteArray(0))
                }
            } finally {
                conn.disconnect()
            }
        }
        return BinaryResponse(310, ByteArray(0))
    }

    private fun apiError(body: String): String = runCatching {
        JSONObject(body).optString("message").ifBlank { body.take(180) }
    }.getOrDefault(body.take(180)).ifBlank { "нет описания" }

    /** Реальный статус выбранной job; failure/cancelled являются терминальными. */
    private fun fetchRunState(
        token: String,
        sessionId: String,
        os: String,
        workflow: String = WORKFLOW,
        stepText: (String) -> String? = ::llmStepText,
    ): RunState {
        return runCatching {
            val runsResponse = githubRequest(
                token,
                "https://api.github.com/repos/$REPO/actions/workflows/$workflow/runs" +
                    "?event=workflow_dispatch&per_page=20",
            )
            if (runsResponse.code !in 200..299) {
                return RunState(message = "GitHub API ${runsResponse.code}: ${apiError(runsResponse.body)}")
            }
            val runs = JSONObject(runsResponse.body).getJSONArray("workflow_runs")
            var run: JSONObject? = null
            for (i in 0 until runs.length()) {
                val candidate = runs.getJSONObject(i)
                if (candidate.optString("display_title").contains(sessionId)) {
                    run = candidate
                    break
                }
            }
            val foundRun = run ?: return RunState(message = "⏳ Запуск принят, ждём ранер GitHub…")
            val runId = foundRun.getLong("id")
            val runStatus = foundRun.optString("status")
            val runConclusion = foundRun.optString("conclusion")
            if (runStatus == "queued" || runStatus == "waiting" || runStatus == "pending") {
                return RunState(runId = runId, message = "⏳ Ранер в очереди GitHub…")
            }

            val jobsResponse = githubRequest(
                token,
                "https://api.github.com/repos/$REPO/actions/runs/$runId/jobs?per_page=20",
            )
            if (jobsResponse.code !in 200..299) {
                return RunState(
                    runId = runId,
                    terminal = runStatus == "completed",
                    message = "GitHub jobs API ${jobsResponse.code}: ${apiError(jobsResponse.body)}",
                )
            }
            val jobs = JSONObject(jobsResponse.body).getJSONArray("jobs")
            val wantedName = "serve-$os"
            var job: JSONObject? = null
            for (i in 0 until jobs.length()) {
                val candidate = jobs.getJSONObject(i)
                if (candidate.optString("name") == wantedName) {
                    job = candidate
                    break
                }
            }
            if (job == null) {
                for (i in 0 until jobs.length()) {
                    val candidate = jobs.getJSONObject(i)
                    if (candidate.optString("conclusion") != "skipped") {
                        job = candidate
                        break
                    }
                }
            }

            val selectedJob = job
            val completed = runStatus == "completed" || selectedJob?.optString("status") == "completed"
            val conclusion = selectedJob?.optString("conclusion").orEmpty().ifBlank { runConclusion }
            val steps = selectedJob?.optJSONArray("steps")
            if (completed) {
                var failedStep = ""
                if (steps != null) {
                    for (i in 0 until steps.length()) {
                        val step = steps.getJSONObject(i)
                        if (step.optString("conclusion") in setOf("failure", "cancelled", "timed_out")) {
                            failedStep = step.optString("name")
                            break
                        }
                    }
                }
                val detail = when (conclusion) {
                    "cancelled" -> "запуск отменён"
                    "timed_out" -> "превышен лимит времени"
                    "success" -> "job завершилась до публикации endpoint"
                    else -> "ошибка запуска"
                }
                return RunState(
                    runId = runId,
                    terminal = true,
                    message = "❌ $detail" +
                        failedStep.takeIf { it.isNotBlank() }?.let { " • шаг: $it" }.orEmpty() +
                        " • run #$runId",
                )
            }

            if (steps != null) {
                for (i in 0 until steps.length()) {
                    val step = steps.getJSONObject(i)
                    if (step.optString("status") == "in_progress") {
                        val name = step.optString("name")
                        val text = stepText(name) ?: name
                        return RunState(runId = runId, message = "▶ $text")
                    }
                }
            }
            RunState(runId = runId, message = "▶ Ранер запускается…")
        }.getOrElse {
            RunState(runId = null, message = "Временная ошибка статуса: ${it.message ?: "сеть"}")
        }
    }

    /** Человекочитаемые статусы этапов llm-runner.yml. */
    private fun llmStepText(name: String): String? = when {
        name.startsWith("Restore model cache") -> "Проверяем кэш модели…"
        name.startsWith("Download llama.cpp") -> "Скачивается llama.cpp…"
        name.startsWith("Download GGUF") -> "Скачивается модель в ранер…"
        name.startsWith("Save model cache") -> "Сохраняем модель в кэш…"
        name.startsWith("Start server") -> "Запускаются сервер и туннель…"
        name.startsWith("Upload endpoint") -> "Публикуется endpoint…"
        name.startsWith("Keep session") -> "Ранер готов, забираем endpoint…"
        else -> null
    }

    /** Человекочитаемые статусы этапов opencode.yml. */
    private fun opencodeStepText(name: String): String? = when {
        name.startsWith("Prepare working branch") -> "Готовится рабочая ветка…"
        name.startsWith("Install npm-hub") -> "Ставятся npm-hub зависимости…"
        name.startsWith("Start npm-hub") -> "Запускается сайт-хаб и туннель…"
        name.startsWith("Upload endpoint") -> "Публикуется endpoint…"
        name.startsWith("Keep session") -> "Ранер готов, забираем endpoint…"
        else -> null
    }

    /** Ищет endpoint только внутри нужного run, скачивает zip и читает JSON. */
    private fun fetchEndpointArtifact(
        token: String,
        runId: Long,
        sessionId: String,
    ): Triple<String, String, String>? {
        return runCatching {
            val response = githubRequest(
                token,
                "https://api.github.com/repos/$REPO/actions/runs/$runId/artifacts?per_page=100",
            )
            if (response.code !in 200..299) return null
            val artifacts = JSONObject(response.body).getJSONArray("artifacts")
            var downloadUrl: String? = null
            for (i in 0 until artifacts.length()) {
                val artifact = artifacts.getJSONObject(i)
                if (
                    artifact.getString("name") == "endpoint-$sessionId" &&
                    !artifact.getBoolean("expired")
                ) {
                    downloadUrl = artifact.getString("archive_download_url")
                    break
                }
            }
            val url = downloadUrl ?: return null
            val zipResponse = githubDownload(token, url)
            if (zipResponse.code !in 200..299 || zipResponse.body.isEmpty()) return null
            var endpointJson: String? = null
            ZipInputStream(zipResponse.body.inputStream()).use { zis ->
                var entry = zis.nextEntry
                while (entry != null) {
                    if (entry.name == "endpoint.json") {
                        endpointJson = zis.readBytes().toString(Charsets.UTF_8)
                        break
                    }
                    entry = zis.nextEntry
                }
            }
            val endpoint = JSONObject(endpointJson ?: return null)
            Triple(
                endpoint.getString("url"),
                endpoint.getString("api_key"),
                endpoint.optString("terminal"),
            )
        }.getOrNull()
    }

    /** Чат с ранером: OpenAI-совместимый endpoint llama.cpp. */
    suspend fun chat(context: Context, session: Session, userText: String): String? =
        withContext(Dispatchers.IO) {
            val url = session.url ?: return@withContext null
            val key = session.apiKey ?: return@withContext null
            // Запрос строится из КОПИИ истории: мутация session.messages
            // происходит только при успешном ответе, поэтому при сбое сети в
            // сессию не попадает «фантомная» копия вопроса, а диалог не
            // расходится с тем, что реально ушло в ранер.
            val messages = JSONArray()
            (ArrayList(session.messages) + ("user" to userText)).takeLast(24).forEach { (r, c) ->
                messages.put(JSONObject().put("role", r).put("content", c))
            }
            val answer = runCatching {
                // Туннель cloudflared тоже может требовать прокси (как chat.try.ai).
                val conn = AiAssistant.openConnection("$url/v1/chat/completions") as HttpURLConnection
                conn.requestMethod = "POST"
                conn.doOutput = true
                conn.connectTimeout = 20_000
                conn.readTimeout = 180_000
                conn.setRequestProperty("Content-Type", "application/json")
                conn.setRequestProperty("Authorization", "Bearer $key")
                val body = JSONObject()
                    .put("model", session.model)
                    .put("messages", messages)
                    .put("max_tokens", 800)
                conn.outputStream.use { it.write(body.toString().toByteArray()) }
                val text = (if (conn.responseCode in 200..299) conn.inputStream else conn.errorStream)
                    ?.use { it.readBytes().toString(Charsets.UTF_8) }.orEmpty()
                conn.disconnect()
                JSONObject(text).optJSONArray("choices")?.optJSONObject(0)
                    ?.optJSONObject("message")?.optString("content")?.trim()
            }.onFailure {
                logcat(LogPriority.WARN, it) { "Runner LLM chat failed" }
            }.getOrNull()
            if (answer != null) {
                synchronized(session.messages) {
                    session.messages += "user" to userText
                    session.messages += "assistant" to answer
                }
                saveSession(context, session)
            }
            answer
        }

    /** Жива ли сессия (реальный запрос /health к туннелю). */
    suspend fun isAlive(session: Session): Boolean = withContext(Dispatchers.IO) {
        val url = session.url ?: return@withContext false
        runCatching {
            val conn = AiAssistant.openConnection("$url/health") as HttpURLConnection
            conn.connectTimeout = 8_000
            conn.readTimeout = 8_000
            session.apiKey?.let { conn.setRequestProperty("Authorization", "Bearer $it") }
            val ok = conn.responseCode in 200..299
            conn.disconnect()
            ok
        }.getOrDefault(false)
    }

    /** Статус ранера для индикации в UI. */
    data class RunnerStatus(
        val alive: Boolean,
        /** Аптайм сессии, мс (от createdAt). */
        val uptimeMs: Long,
        /** Осталось до 5.5-часового лимита job, мс. */
        val remainingMs: Long,
        /** Время последней проверки. */
        val checkedAt: Long,
    )

    private const val SESSION_LIFETIME_MS = 330L * 60_000L // 5.5 часов

    /**
     * ИНДИКАЦИЯ РАНЕРА (по требованию пользователя): живой /health-пинг +
     * аптайм + сколько осталось до конца сессии.
     */
    suspend fun status(session: Session): RunnerStatus {
        val alive = isAlive(session)
        val uptime = System.currentTimeMillis() - session.createdAt
        return RunnerStatus(
            alive = alive,
            uptimeMs = uptime,
            remainingMs = (SESSION_LIFETIME_MS - uptime).coerceAtLeast(0),
            checkedAt = System.currentTimeMillis(),
        )
    }

    /**
     * Своя GGUF-модель ПО ССЫЛКЕ: воркфлоу принимает custom_url — ранер
     * скачает её вместо каталожной. Размер неизвестен заранее — воркфлоу
     * напишет его в лог, а стартовый статус покажет прогресс этапов.
     */
    suspend fun startSessionWithUrl(
        context: Context,
        ggufUrl: String,
        onStatus: (String) -> Unit,
        os: String = "linux",
    ): Session? = startSessionInternal(context, "custom", ggufUrl, onStatus, os)

    /**
     * Запуск сессии OpenCode-агента (workflow opencode.yml): на GitHub-ранере
     * поднимаются opencode serve + oc-gateway (веб/мобильный чат) и npm-hub
     * (xterm-терминал, файлы, логи, git status/diff/log), всё открывается
     * cloudflared-туннелями. endpoint-артефакт несёт два адреса:
     *   url       — чат с агентом (oc-gateway);
     *   terminal  — npm-hub (терминал/файлы/дашборд).
     * Агент работает PAT-ом аккаунта (YP_AGENT_TOKEN), поэтому видит и меняет
     * ВСЕ репозитории, коммиты и логи аккаунта, а не только этот репозиторий.
     */
    suspend fun startOpenCode(
        context: Context,
        onStatus: (String) -> Unit,
        os: String = "linux",
        ui: String = "mobile",
        branch: String = "opencode-work",
    ): Session? = withContext(Dispatchers.IO) {
        val token = prefs().githubPat().get()
        if (token.isBlank()) {
            onStatus("Нет GitHub-токена: задайте PAT в настройках выше")
            return@withContext null
        }
        val selectedOs = if (os == "windows") "windows" else "linux"
        val session = Session(
            id = "oc" + System.currentTimeMillis().toString(36) + (1000..9999).random(),
            model = "hub",
            os = selectedOs,
        )

        onStatus("Отправляем запуск OpenCode в GitHub Actions…")
        val dispatchBody = JSONObject()
            .put("ref", OPENCODE_REF)
            .put(
                "inputs",
                JSONObject()
                    .put("session", session.id)
                    .put("os", selectedOs)
                    .put("ui", ui)
                    .put("branch", branch),
            )
        val dispatch = runCatching {
            githubRequest(
                token = token,
                url = "https://api.github.com/repos/$REPO/actions/workflows/$WORKFLOW_OPENCODE/dispatches",
                method = "POST",
                body = dispatchBody.toString(),
            )
        }.getOrElse {
            onStatus("Не удалось связаться с GitHub: ${it.message ?: "ошибка сети"}")
            return@withContext null
        }
        if (dispatch.code !in 200..299) {
            onStatus("GitHub отклонил запуск (${dispatch.code}): ${apiError(dispatch.body)}")
            return@withContext null
        }

        val deadline = System.currentTimeMillis() + START_TIMEOUT_MS
        var lastStatus = ""
        var runId: Long? = null
        while (System.currentTimeMillis() < deadline) {
            val state = fetchRunState(
                token, session.id, selectedOs,
                workflow = WORKFLOW_OPENCODE, stepText = ::opencodeStepText,
            )
            runId = state.runId ?: runId
            if (state.message != lastStatus) {
                onStatus(state.message)
                lastStatus = state.message
            }

            runId?.let { id ->
                fetchEndpointArtifact(token, id, session.id)?.let { endpoint ->
                    session.url = endpoint.first
                    session.apiKey = endpoint.second
                    session.terminalUrl = endpoint.third.ifBlank { null }
                    saveSession(context, session)
                    onStatus("✅ OpenCode-агент готов: ${endpoint.first}")
                    return@withContext session
                }
            }

            if (state.terminal) {
                onStatus(state.message)
                return@withContext null
            }
            delay(POLL_INTERVAL_MS)
        }
        onStatus(
            if (runId == null) {
                "Таймаут: GitHub не создал запуск за ${START_TIMEOUT_MS / 60_000} минут"
            } else {
                "Таймаут: endpoint не появился за ${START_TIMEOUT_MS / 60_000} минут. " +
                    "Последний статус: ${lastStatus.ifBlank { "неизвестен" }}"
            },
        )
        null
    }
}

